#!/usr/bin/env python3
# /// script
# name: register-package
# purpose: Validate and atomically register one promoted exact-13 system-dev-planner package in the dev graph.
# inputs: ["argv: register --package/--graph/--output/--receipt", "argv: execution-context --graph/--graph-node-id/--context-json", "argv: preflight"]
# outputs: ["stdout: JSON preview/receipt/preflight report"]
# requires-python = ">=3.10"
# dependencies: [_common.py]
# contexts: [A, B, C, E]
# network: false
# write-scope: explicitly selected dev-graph output and immutable receipt
# ///
"""C02 exact-13 package registration consumer and cross-plugin preflight."""
from __future__ import annotations

import argparse
import copy
import fcntl
import hashlib
import json
import os
import re
import sys
import tempfile
from contextlib import contextmanager
from pathlib import Path
from typing import Any, Iterator

from _common import ContractError, atomic_json, contained, dump, load_json, utc_now

HERE = Path(__file__).resolve().parent
PLUGIN_ROOT = HERE.parent
DEFAULT_SYSTEM_ROOT = PLUGIN_ROOT.parent / "system-dev-planner"
PHASES = [f"P{i:02d}" for i in range(1, 14)]
SHA256 = re.compile(r"^sha256:[0-9a-f]{64}$")
HEX_SHA256 = re.compile(r"^[0-9a-f]{64}$")
REGISTRATION_KEYS = {
    "schema_version", "source_digest", "promotion_receipt", "feature_package_id",
    "parent_feature", "expected_count", "phase_refs", "binding_intents", "nodes",
}
RECEIPT_STABLE_KEYS = {
    "schema_version", "status", "feature_package_id", "parent_feature", "source_digest",
    "expected_count", "applied_count", "phase_refs", "node_ids", "graph_revision_before",
    "graph_revision_after", "graph_digest_after", "output_path",
}


def _schema_error(path: str, detail: str) -> ContractError:
    return ContractError(f"schema violation at {path}: {detail}")


def _is_type(value: Any, expected: str) -> bool:
    if expected == "null": return value is None
    if expected == "object": return isinstance(value, dict)
    if expected == "array": return isinstance(value, list)
    if expected == "string": return isinstance(value, str)
    if expected == "boolean": return isinstance(value, bool)
    if expected == "integer": return isinstance(value, int) and not isinstance(value, bool)
    if expected == "number": return isinstance(value, (int, float)) and not isinstance(value, bool)
    return True


def _matches(value: Any, schema: Any, root: dict[str, Any]) -> bool:
    try:
        _validate_schema(value, schema, root, "$")
        return True
    except ContractError:
        return False


def _validate_schema(value: Any, schema: Any, root: dict[str, Any], path: str) -> None:
    """Validate the stdlib-only subset used by the local package/node schemas."""
    if schema is True: return
    if schema is False: raise _schema_error(path, "value is forbidden")
    if not isinstance(schema, dict): raise _schema_error(path, "invalid schema object")
    ref = schema.get("$ref")
    if isinstance(ref, str):
        if not ref.startswith("#/"):
            raise _schema_error(path, f"external $ref is not supported here: {ref}")
        target: Any = root
        for part in ref[2:].split("/"):
            target = target[part.replace("~1", "/").replace("~0", "~")]
        _validate_schema(value, target, root, path)
    for child in schema.get("allOf", []): _validate_schema(value, child, root, path)
    if "if" in schema and _matches(value, schema["if"], root) and "then" in schema:
        _validate_schema(value, schema["then"], root, path)
    expected = schema.get("type")
    if expected is not None:
        choices = expected if isinstance(expected, list) else [expected]
        if not any(_is_type(value, item) for item in choices):
            raise _schema_error(path, f"expected type {choices}, got {type(value).__name__}")
    if "const" in schema and value != schema["const"]:
        raise _schema_error(path, f"expected const {schema['const']!r}")
    if "enum" in schema and value not in schema["enum"]:
        raise _schema_error(path, f"not in enum {schema['enum']!r}")
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0): raise _schema_error(path, "string too short")
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            raise _schema_error(path, f"does not match {schema['pattern']}")
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]: raise _schema_error(path, "below minimum")
        if "maximum" in schema and value > schema["maximum"]: raise _schema_error(path, "above maximum")
    if isinstance(value, list):
        if len(value) < schema.get("minItems", 0): raise _schema_error(path, "too few items")
        if "maxItems" in schema and len(value) > schema["maxItems"]: raise _schema_error(path, "too many items")
        if schema.get("uniqueItems"):
            packed = [json.dumps(x, sort_keys=True, separators=(",", ":")) for x in value]
            if len(set(packed)) != len(packed): raise _schema_error(path, "items are not unique")
        prefix = schema.get("prefixItems", [])
        for index, child in enumerate(prefix[:len(value)]):
            _validate_schema(value[index], child, root, f"{path}[{index}]")
        items = schema.get("items")
        if items is False and len(value) > len(prefix): raise _schema_error(path, "additional items forbidden")
        if isinstance(items, dict):
            for index, item in enumerate(value): _validate_schema(item, items, root, f"{path}[{index}]")
        if "contains" in schema and not any(_matches(item, schema["contains"], root) for item in value):
            raise _schema_error(path, "contains constraint not satisfied")
    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value: raise _schema_error(path, f"missing required property {key}")
        props = schema.get("properties", {})
        for key, child in props.items():
            if key in value: _validate_schema(value[key], child, root, f"{path}.{key}")
        additional = schema.get("additionalProperties", True)
        unknown = set(value) - set(props)
        if additional is False and unknown: raise _schema_error(path, f"unknown properties {sorted(unknown)}")
        if isinstance(additional, dict):
            for key in unknown: _validate_schema(value[key], additional, root, f"{path}.{key}")
        if len(value) < schema.get("minProperties", 0): raise _schema_error(path, "too few properties")
        if "maxProperties" in schema and len(value) > schema["maxProperties"]:
            raise _schema_error(path, "too many properties")


def _path(root: Path, raw: str, *, must_exist: bool) -> Path:
    candidate = Path(raw)
    if not candidate.is_absolute(): candidate = root / candidate
    if must_exist: return contained(candidate, root, must_exist=True)
    parent = contained(candidate.parent, root, must_exist=True)
    return parent / candidate.name


def _json_object(path: Path) -> dict[str, Any]:
    value = load_json(path)
    if not isinstance(value, dict): raise ContractError(f"JSON object required: {path}")
    return value


def _canonical_digest(value: Any) -> str:
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
    return "sha256:" + hashlib.sha256(raw).hexdigest()


def _schema_version(schema: dict[str, Any], name: str) -> str:
    value = (((schema.get("properties") or {}).get("schema_version") or {}).get("const"))
    if not isinstance(value, str): raise ContractError(f"{name} does not pin properties.schema_version.const")
    return value


def preflight_contract(system_root: Path, required_version: str | None, required_schema_version: str) -> dict[str, Any]:
    root = system_root.resolve(strict=True)
    manifest = _json_object(root / ".claude-plugin" / "plugin.json")
    if manifest.get("name") != "system-dev-planner": raise ContractError("unexpected upstream plugin name")
    # 既定は literal pin を置かない: upstream の patch bump で必ず外れる一方、契約の
    # 実体は entry_points と schema_version const が固定する。呼び出し側が
    # --required-version を明示したときだけ従来どおり厳密一致を要求する。
    observed_version = manifest.get("version")
    if not isinstance(observed_version, str) or re.fullmatch(r"\d+\.\d+\.\d+", observed_version) is None:
        raise ContractError(f"system-dev-planner version is missing or not semver: {observed_version!r}")
    if required_version is not None and observed_version != required_version:
        raise ContractError(f"system-dev-planner version mismatch: expected {required_version}, got {observed_version}")
    package_contract = _json_object(root / "references" / "package-contract.json")
    if package_contract.get("plugin_name") != "system-dev-planner":
        raise ContractError("system-dev-planner package contract identity mismatch")
    entry_points = package_contract.get("entry_points")
    if not isinstance(entry_points, dict):
        raise ContractError("system-dev-planner package contract entry_points missing")
    required = {
        "skills": ["run-system-dev-plan", "assign-system-dev-plan-evaluator"],
        "agents": ["system-dev-plan-elicitor", "system-dev-plan-architect", "system-dev-plan-evaluator"],
        "commands": ["system-dev-plan"],
    }
    suffixes = {"skills": "SKILL.md", "agents": ".md", "commands": ".md"}
    for kind, names in required.items():
        declared = entry_points.get(kind)
        if not isinstance(declared, list) or not set(names).issubset(set(declared)):
            raise ContractError(f"missing required {kind} entrypoints: {sorted(set(names) - set(declared or []))}")
        for name in names:
            physical = root / kind / name / suffixes[kind] if kind == "skills" else root / kind / f"{name}{suffixes[kind]}"
            if not physical.is_file(): raise ContractError(f"declared entrypoint is missing: {physical}")
    schemas = {}
    for filename in ("feature-execution-package.schema.json", "dev-graph-registration.schema.json"):
        schema = _json_object(root / "schemas" / filename)
        version = _schema_version(schema, filename)
        if version != required_schema_version:
            raise ContractError(f"{filename} version mismatch: expected {required_schema_version}, got {version}")
        schemas[filename] = version
    for filename in ("validate-system-plan.py", "promote-system-plan.py"):
        if not (root / "scripts" / filename).is_file(): raise ContractError(f"required upstream script missing: {filename}")
    return {"valid": True, "plugin": "system-dev-planner", "version": observed_version,
            "entrypoint_source": "references/package-contract.json",
            "schema_versions": schemas, "required_entrypoints": required}


def _validate_package(package: dict[str, Any], schema: dict[str, Any]) -> None:
    _validate_schema(package, schema, schema, "feature-package")
    if package["phase_refs"] != PHASES or package["task_count"] != 13:
        raise ContractError("feature package is not exact P01..P13")


def _validate_registration(registration: dict[str, Any], package: dict[str, Any], node_schema: dict[str, Any]) -> list[dict[str, Any]]:
    if set(registration) != REGISTRATION_KEYS:
        raise ContractError(f"registration keys mismatch: {sorted(set(registration) ^ REGISTRATION_KEYS)}")
    if registration.get("schema_version") != "1.0.0": raise ContractError("registration schema_version must be 1.0.0")
    if not SHA256.fullmatch(str(registration.get("source_digest", ""))): raise ContractError("invalid source_digest")
    if registration.get("expected_count") != 13 or registration.get("phase_refs") != PHASES:
        raise ContractError("registration is not exact P01..P13")
    if registration.get("feature_package_id") != package.get("feature_package_id"):
        raise ContractError("feature_package_id mismatch")
    if registration.get("parent_feature") != package.get("parent_feature"):
        raise ContractError("parent_feature mismatch")
    nodes = registration.get("nodes")
    if not isinstance(nodes, list) or len(nodes) != 13: raise ContractError("registration nodes must contain exactly 13 objects")
    phases = [node.get("phase_ref") if isinstance(node, dict) else None for node in nodes]
    if phases != PHASES: raise ContractError(f"node phase exact-set mismatch: {phases}")
    node_ids = [node.get("graph_node_id") if isinstance(node, dict) else None for node in nodes]
    if node_ids != package.get("task_node_ids") or len(set(node_ids)) != 13:
        raise ContractError("node ids must equal package.task_node_ids in phase order")
    intents = registration.get("binding_intents")
    if not isinstance(intents, dict) or set(intents) != set(node_ids):
        raise ContractError("binding_intents keys must equal exact node id set")
    if any(value not in {"auto", "beads", "github", "none"} for value in intents.values()):
        raise ContractError("invalid binding intent")
    phase_number = {node_ids[i]: i + 1 for i in range(13)}
    source_digest = registration["source_digest"].removeprefix("sha256:")
    for index, node in enumerate(nodes):
        if not isinstance(node, dict): raise ContractError(f"nodes[{index}] must be an object")
        _validate_schema(node, node_schema, node_schema, f"nodes[{index}]")
        if node.get("artifact_kind") != "task" or node.get("artifact_subtypes") != []:
            raise ContractError(f"nodes[{index}] must be a canonical task")
        if node.get("parent_feature") != package["parent_feature"] or node.get("feature_package_id") != package["feature_package_id"]:
            raise ContractError(f"nodes[{index}] has mixed parent/package")
        if node.get("tracker_binding") != "repo-config-default":
            raise ContractError(f"nodes[{index}] must carry unresolved repo-config-default binding")
        if node.get("status") != "active" or node.get("confirmation_status") != "confirmed" or node.get("evaluation_status") != "pass":
            raise ContractError(f"nodes[{index}] is not confirmed active/pass")
        if (node.get("implementation_readiness") or {}).get("status") != "complete":
            raise ContractError(f"nodes[{index}] implementation readiness is incomplete")
        lineage = node.get("source_lineage") or {}
        if lineage.get("origin_kind") != "system-dev-planner" or lineage.get("source_plugin") != "system-dev-planner":
            raise ContractError(f"nodes[{index}] has invalid system-dev-planner lineage")
        if lineage.get("source_digest") != source_digest:
            raise ContractError(f"nodes[{index}] source lineage digest mismatch")
        if not str(node.get("file_path", "")).startswith("tasks/"):
            raise ContractError(f"nodes[{index}] file_path is not under tasks/")
        parent_feature = node.get("parent_feature")
        if isinstance(parent_feature, str) and parent_feature:
            # feature 単位 namespace: 並列 package 登録・worktree 並列実行時の
            # tasks/ 直下衝突を防ぐ (parent_feature 無しの fast-path task は対象外)
            if not str(node.get("file_path", "")).startswith(f"tasks/{parent_feature}/"):
                raise ContractError(
                    f"nodes[{index}] file_path must be under tasks/{parent_feature}/ (per-feature namespace)"
                )
        for dependency in node.get("depends_on", []):
            if dependency not in phase_number: raise ContractError(f"cross-package dependency rejected: {dependency}")
            if phase_number[dependency] >= index + 1: raise ContractError(f"non-forward phase dependency rejected: {dependency}")
    return copy.deepcopy(nodes)


def _resolve_binding(intent: str, mode: str) -> str:
    if intent == "auto":
        if mode == "both": raise ContractError("tracker mode both requires an explicit binding intent for every node")
        return mode
    if intent == "none": return "none"
    if mode not in {intent, "both"}: raise ContractError(f"binding intent {intent} is not allowed by tracker mode {mode}")
    return intent


def _resolved_nodes(nodes: list[dict[str, Any]], intents: dict[str, str], mode: str,
                    node_schema: dict[str, Any]) -> list[dict[str, Any]]:
    result = copy.deepcopy(nodes)
    for index, node in enumerate(result):
        node_id = node["graph_node_id"]
        binding = _resolve_binding(intents[node_id], mode)
        node["tracker_binding"] = binding
        publication = node["github_publication"]
        if binding == "github":
            if publication.get("mode") not in {"issue", "issue_and_projects"}: publication["mode"] = "issue"
        else:
            publication["mode"] = "local_only"
            publication["project_aliases"] = []
        if binding in {"github", "none"}: node["beads_linkage"] = None
        _validate_schema(node, node_schema, node_schema, f"resolved_nodes[{index}]")
        if node["tracker_binding"] == "repo-config-default": raise ContractError("unresolved binding sentinel")
    return result


def _promotion_matches(root: Path, registration_path: Path, registration: dict[str, Any]) -> None:
    raw = registration.get("promotion_receipt")
    if not isinstance(raw, str): raise ContractError("promotion_receipt path missing")
    receipt_path = _path(root, raw, must_exist=True)
    receipt = _json_object(receipt_path)
    if receipt.get("status") != "promoted": raise ContractError("promotion receipt status is not promoted")
    if receipt.get("published_digest") != registration["source_digest"]:
        raise ContractError("promotion/registration digest mismatch")
    manifest = receipt.get("registration_manifest")
    if isinstance(manifest, str):
        manifest_path = _path(root, manifest, must_exist=True)
        if manifest_path != registration_path: raise ContractError("promotion receipt points to a different registration manifest")


def _find_node(nodes: list[dict[str, Any]], node_id: str) -> dict[str, Any] | None:
    return next((node for node in nodes if (node.get("graph_node_id") or node.get("id")) == node_id), None)


def _stable_receipt(value: dict[str, Any]) -> dict[str, Any]:
    return {key: value.get(key) for key in RECEIPT_STABLE_KEYS}


def _atomic_create_json(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(value, stream, ensure_ascii=False, sort_keys=True, indent=2)
            stream.write("\n"); stream.flush(); os.fsync(stream.fileno())
        try: os.link(temp, path)
        except FileExistsError as exc: raise ContractError(f"immutable receipt already exists: {path}") from exc
    finally:
        try: os.unlink(temp)
        except FileNotFoundError: pass


@contextmanager
def _single_writer(output: Path) -> Iterator[None]:
    lock_path = output.with_name(f".{output.name}.register.lock")
    with lock_path.open("a+", encoding="utf-8") as stream:
        try: fcntl.flock(stream.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc: raise ContractError(f"registration writer is already active: {output}") from exc
        yield


def _register(args: argparse.Namespace) -> dict[str, Any]:
    root = Path(args.repo_root or os.getcwd()).resolve(strict=True)
    package_path = _path(root, args.package, must_exist=True)
    registration_path = _path(root, args.graph, must_exist=True)
    output_path = _path(root, args.output, must_exist=True)
    receipt_path = _path(root, args.receipt, must_exist=False)
    system_root = Path(args.system_planner_root).resolve(strict=True)
    preflight_contract(system_root, args.required_version, args.required_schema_version)
    package_schema = _json_object(system_root / "schemas" / "feature-execution-package.schema.json")
    registration_schema = _json_object(system_root / "schemas" / "dev-graph-registration.schema.json")
    if _schema_version(registration_schema, "dev-graph-registration.schema.json") != args.required_schema_version:
        raise ContractError("registration schema version changed after preflight")
    node_schema = _json_object(PLUGIN_ROOT / "schemas" / "graph-node.schema.json")
    receipt_schema = _json_object(PLUGIN_ROOT / "schemas" / "package-registration-receipt.schema.json")
    package = _json_object(package_path); _validate_package(package, package_schema)
    registration = _json_object(registration_path)
    incoming = _validate_registration(registration, package, node_schema)
    _promotion_matches(root, registration_path, registration)
    resolved = _resolved_nodes(incoming, registration["binding_intents"], args.tracker_mode, node_schema)

    def perform() -> dict[str, Any]:
        current = _json_object(output_path)
        existing = current.get("nodes")
        if not isinstance(existing, list) or not all(isinstance(node, dict) for node in existing):
            raise ContractError("output graph must contain nodes[] objects")
        existing_ids = [node.get("graph_node_id") or node.get("id") for node in existing]
        if len(set(existing_ids)) != len(existing_ids): raise ContractError("output graph contains duplicate node ids")
        for index, node in enumerate(existing):
            _validate_schema(node, node_schema, node_schema, f"output.nodes[{index}]")
        parent = _find_node(existing, package["parent_feature"])
        if not parent or parent.get("artifact_kind", parent.get("kind")) != "feature":
            raise ContractError(f"parent feature does not exist: {package['parent_feature']}")
        incoming_ids = [node["graph_node_id"] for node in resolved]
        present = {node_id for node_id in incoming_ids if _find_node(existing, node_id)}
        package_members = [node for node in existing if node.get("feature_package_id") == package["feature_package_id"]]
        if present and len(present) != 13: raise ContractError(f"partial registration detected: {len(present)}/13 nodes")
        if package_members and {node.get("graph_node_id") for node in package_members} != set(incoming_ids):
            raise ContractError("conflicting or partial feature_package_id already exists")
        revision_before = current.get("graph_revision", 0)
        if not isinstance(revision_before, int) or revision_before < 0: raise ContractError("invalid graph_revision")
        if len(present) == 13:
            actual = [_find_node(existing, node_id) for node_id in incoming_ids]
            if actual != resolved: raise ContractError("duplicate node ids exist with different content")
            if not receipt_path.is_file(): raise ContractError("registered nodes exist without immutable receipt")
            receipt = _json_object(receipt_path)
            _validate_schema(receipt, receipt_schema, receipt_schema, "registration-receipt")
            expected_receipt_identity = {
                "schema_version": "1.0.0", "status": "registered",
                "feature_package_id": package["feature_package_id"],
                "parent_feature": package["parent_feature"],
                "source_digest": registration["source_digest"],
                "expected_count": 13, "applied_count": 13,
                "phase_refs": PHASES, "node_ids": incoming_ids,
                "output_path": output_path.relative_to(root).as_posix(),
            }
            if any(receipt.get(key) != value for key, value in expected_receipt_identity.items()):
                raise ContractError("immutable receipt conflicts with registered package")
            before = receipt.get("graph_revision_before")
            after = receipt.get("graph_revision_after")
            if not isinstance(before, int) or not isinstance(after, int) or after != before + 1 or after > revision_before:
                raise ContractError("immutable receipt graph revision conflicts with registered package")
            return {**receipt, "idempotent": True, "dry_run": bool(args.dry_run)}
        if receipt_path.exists(): raise ContractError("immutable receipt exists before graph registration")
        proposed = copy.deepcopy(current)
        proposed["nodes"] = [*existing, *resolved]
        proposed["graph_revision"] = revision_before + 1
        graph_digest = _canonical_digest(proposed)
        receipt = {
            "schema_version": "1.0.0", "status": "registered", "registered_at": utc_now(),
            "feature_package_id": package["feature_package_id"], "parent_feature": package["parent_feature"],
            "source_digest": registration["source_digest"], "expected_count": 13, "applied_count": 13,
            "phase_refs": PHASES, "node_ids": incoming_ids, "graph_revision_before": revision_before,
            "graph_revision_after": revision_before + 1, "graph_digest_after": graph_digest,
            "output_path": output_path.relative_to(root).as_posix(),
        }
        _validate_schema(receipt, receipt_schema, receipt_schema, "registration-receipt")
        if args.dry_run:
            return {**receipt, "dry_run": True, "idempotent": False, "write_count": 0}
        original = copy.deepcopy(current)
        atomic_json(output_path, proposed)
        try: _atomic_create_json(receipt_path, receipt)
        except Exception:
            atomic_json(output_path, original)
            raise
        return {**receipt, "dry_run": False, "idempotent": False}

    if args.dry_run: return perform()
    with _single_writer(output_path): return perform()


def _project_execution_context(args: argparse.Namespace) -> dict[str, Any]:
    """C02-owned durable projection consumed by C27 after each lease transition."""
    root = Path(args.repo_root or ".").resolve(strict=True)
    graph_path = contained(root / args.graph if not Path(args.graph).is_absolute() else Path(args.graph), root)
    try:
        context = json.loads(args.context_json)
    except json.JSONDecodeError as exc:
        raise ContractError("execution context is invalid JSON") from exc
    if not isinstance(context, dict):
        raise ContractError("execution context must be an object")
    node_schema = load_json(PLUGIN_ROOT / "schemas" / "graph-node.schema.json")
    context_schema = node_schema.get("properties", {}).get("execution_contexts", {}).get("items")
    if not isinstance(context_schema, dict):
        raise ContractError("graph-node schema omits execution_contexts item contract")
    _validate_schema(context, context_schema, node_schema, "$.execution_contexts[0]")

    def perform() -> dict[str, Any]:
        graph = load_json(graph_path)
        if not isinstance(graph, dict) or not isinstance(graph.get("nodes"), list):
            raise ContractError("execution-context graph must contain nodes array")
        matches = [node for node in graph["nodes"] if isinstance(node, dict) and (node.get("graph_node_id") or node.get("id")) == args.graph_node_id]
        if len(matches) != 1:
            raise ContractError("execution-context target must resolve exactly one graph node")
        proposed = copy.deepcopy(graph)
        node = next(node for node in proposed["nodes"] if isinstance(node, dict) and (node.get("graph_node_id") or node.get("id")) == args.graph_node_id)
        existing = node.get("execution_contexts", [])
        if not isinstance(existing, list):
            raise ContractError("node execution_contexts must be an array")
        retained = [row for row in existing if not isinstance(row, dict) or row.get("worktree_id") != context["worktree_id"]]
        node["execution_contexts"] = [*retained, context]
        node["updated_at"] = context["last_seen_at"]
        _validate_schema(node, node_schema, node_schema, "$.nodes[target]")
        idempotent = proposed == graph
        revision_before = graph.get("graph_revision")
        if isinstance(revision_before, int) and not idempotent:
            proposed["graph_revision"] = revision_before + 1
        packed = json.dumps(proposed, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()
        receipt = {
            "owner": "C02/run-dev-graph-node",
            "operation": "project_execution_context",
            "status": "preview" if args.dry_run else "applied",
            "graph_node_id": args.graph_node_id,
            "worktree_id": context["worktree_id"],
            "state": context["state"],
            "graph_sha256_after": hashlib.sha256(packed).hexdigest(),
            "graph_revision_before": revision_before,
            "graph_revision_after": proposed.get("graph_revision"),
            "write_count": 0 if args.dry_run or idempotent else 1,
            "idempotent": idempotent,
        }
        if not args.dry_run:
            if not idempotent:
                atomic_json(graph_path, proposed)
            receipt["graph_sha256_after"] = hashlib.sha256(graph_path.read_bytes()).hexdigest()
        return receipt

    if args.dry_run:
        return perform()
    with _single_writer(graph_path):
        return perform()


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Register exact-13 packages or preflight system-dev-planner")
    sub = parser.add_subparsers(dest="command", required=True)
    register = sub.add_parser("register")
    register.add_argument("--repo-root")
    register.add_argument("--package", required=True, help="feature-execution-package JSON")
    register.add_argument("--graph", required=True, help="dev-graph-registration JSON")
    register.add_argument("--output", required=True, help="existing dev graph JSON containing parent feature")
    register.add_argument("--receipt", required=True, help="immutable registration receipt output")
    register.add_argument("--tracker-mode", choices=("beads", "github", "both", "none"), default="none")
    register.add_argument("--dry-run", action="store_true")
    register.add_argument("--system-planner-root", default=str(DEFAULT_SYSTEM_ROOT))
    register.add_argument("--required-version", default=None)
    register.add_argument("--required-schema-version", default="1.0.0")
    preflight = sub.add_parser("preflight")
    preflight.add_argument("--system-planner-root", default=str(DEFAULT_SYSTEM_ROOT))
    preflight.add_argument("--required-version", default=None)
    preflight.add_argument("--required-schema-version", default="1.0.0")
    execution = sub.add_parser("execution-context")
    execution.add_argument("--repo-root")
    execution.add_argument("--graph", required=True)
    execution.add_argument("--graph-node-id", required=True)
    execution.add_argument("--context-json", required=True)
    execution.add_argument("--dry-run", action="store_true")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.command == "preflight":
            report = preflight_contract(Path(args.system_planner_root), args.required_version, args.required_schema_version)
        elif args.command == "execution-context":
            report = _project_execution_context(args)
        else: report = _register(args)
        dump(report); return 0
    except (ContractError, OSError, json.JSONDecodeError, KeyError, TypeError, ValueError) as exc:
        dump({"valid": False, "error": str(exc)}); return 2


if __name__ == "__main__": raise SystemExit(main())

#!/usr/bin/env python3
# /// script
# name: validate-graph-schema
# purpose: Perform side-effect-free fail-closed validation of canonical dev-graph nodes, artifacts, and feature packages.
# inputs: ["argv: --graph FILE --repo-root PATH?"]
# outputs: ["stdout: JSON validation report"]
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
from __future__ import annotations

import argparse
import json
import re
import sys
from collections import Counter, defaultdict
from datetime import date, datetime
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import urlsplit

from _common import ContractError, contained, dump, load_json

PLUGIN_ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = PLUGIN_ROOT / "schemas" / "graph-node.schema.json"
TEMPLATE_CONTRACT_PATH = PLUGIN_ROOT / "templates" / "template-contract.json"
PHASES = {f"P{i:02d}" for i in range(1, 14)}
ROOT_BY_KIND = {
    "issue": "issues",
    "task": "tasks",
    "specification": "specs",
    "architecture": "architecture",
    "feature": "features",
    "document": "docs",
}


def nodes_of(data: Any) -> list[dict[str, Any]]:
    values = data.get("nodes") if isinstance(data, dict) else data
    if not isinstance(values, list) or not all(isinstance(item, dict) for item in values):
        raise ContractError("graph must be an array or an object with nodes[]")
    return values


def _is_type(value: Any, expected: str) -> bool:
    return {
        "null": value is None,
        "object": isinstance(value, dict),
        "array": isinstance(value, list),
        "string": isinstance(value, str),
        "boolean": isinstance(value, bool),
        "integer": isinstance(value, int) and not isinstance(value, bool),
        "number": isinstance(value, (int, float)) and not isinstance(value, bool),
    }.get(expected, True)


def _format_ok(value: str, expected: str) -> bool:
    try:
        if expected == "date":
            date.fromisoformat(value)
        elif expected == "date-time":
            datetime.fromisoformat(value.replace("Z", "+00:00"))
        elif expected == "uri":
            return bool(urlsplit(value).scheme)
    except ValueError:
        return False
    return True


def _schema_fallback(value: Any, schema: Any, root: dict[str, Any], path: str = "$") -> list[tuple[str, str]]:
    """Deterministic Draft 2020-12 subset used if jsonschema is unavailable."""
    if schema is True:
        return []
    if schema is False or not isinstance(schema, dict):
        return [(path, "value is forbidden" if schema is False else "invalid schema object")]
    findings: list[tuple[str, str]] = []
    reference = schema.get("$ref")
    if isinstance(reference, str):
        if not reference.startswith("#/"):
            return [(path, f"external schema reference is forbidden: {reference}")]
        target: Any = root
        try:
            for part in reference[2:].split("/"):
                target = target[part.replace("~1", "/").replace("~0", "~")]
        except (KeyError, TypeError):
            return [(path, f"unresolved schema reference: {reference}")]
        findings.extend(_schema_fallback(value, target, root, path))
    for child in schema.get("allOf", []):
        findings.extend(_schema_fallback(value, child, root, path))
    if "if" in schema and not _schema_fallback(value, schema["if"], root, path) and "then" in schema:
        findings.extend(_schema_fallback(value, schema["then"], root, path))
    expected = schema.get("type")
    if expected is not None:
        choices = expected if isinstance(expected, list) else [expected]
        if not any(_is_type(value, choice) for choice in choices):
            return findings + [(path, f"expected type {choices}, got {type(value).__name__}")]
    if "const" in schema and value != schema["const"]:
        findings.append((path, f"expected const {schema['const']!r}"))
    if "enum" in schema and value not in schema["enum"]:
        findings.append((path, f"not in enum {schema['enum']!r}"))
    if isinstance(value, str):
        if len(value) < schema.get("minLength", 0):
            findings.append((path, "string is shorter than minLength"))
        if "pattern" in schema and re.search(schema["pattern"], value) is None:
            findings.append((path, f"does not match {schema['pattern']}"))
        if "format" in schema and not _format_ok(value, schema["format"]):
            findings.append((path, f"invalid {schema['format']} format"))
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if "minimum" in schema and value < schema["minimum"]:
            findings.append((path, "below minimum"))
        if "maximum" in schema and value > schema["maximum"]:
            findings.append((path, "above maximum"))
    if isinstance(value, list):
        if len(value) < schema.get("minItems", 0):
            findings.append((path, "too few items"))
        if "maxItems" in schema and len(value) > schema["maxItems"]:
            findings.append((path, "too many items"))
        if schema.get("uniqueItems"):
            packed = [json.dumps(item, sort_keys=True, separators=(",", ":")) for item in value]
            if len(packed) != len(set(packed)):
                findings.append((path, "items are not unique"))
        items = schema.get("items")
        if isinstance(items, dict):
            for index, item in enumerate(value):
                findings.extend(_schema_fallback(item, items, root, f"{path}[{index}]"))
        if "contains" in schema and not any(not _schema_fallback(item, schema["contains"], root, path) for item in value):
            findings.append((path, "contains constraint is not satisfied"))
    if isinstance(value, dict):
        for key in schema.get("required", []):
            if key not in value:
                findings.append((path, f"missing required property {key}"))
        properties = schema.get("properties", {})
        for key, child in properties.items():
            if key in value:
                findings.extend(_schema_fallback(value[key], child, root, f"{path}.{key}"))
        additional = schema.get("additionalProperties", True)
        unknown = sorted(set(value) - set(properties))
        if additional is False and unknown:
            findings.append((path, f"unknown properties {unknown}"))
        elif isinstance(additional, dict):
            for key in unknown:
                findings.extend(_schema_fallback(value[key], additional, root, f"{path}.{key}"))
    return findings


def schema_findings(node: dict[str, Any], schema: dict[str, Any], index: int) -> list[dict[str, str]]:
    node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
    try:
        from jsonschema import Draft202012Validator, FormatChecker  # type: ignore
    except ImportError:
        raw = _schema_fallback(node, schema, schema)
    else:
        try:
            Draft202012Validator.check_schema(schema)
        except Exception as exc:
            raise ContractError(f"invalid canonical graph schema {SCHEMA_PATH}: {exc}") from exc
        validator = Draft202012Validator(schema, format_checker=FormatChecker())
        errors = sorted(
            validator.iter_errors(node),
            key=lambda err: (tuple(str(part) for part in err.absolute_path), err.message),
        )
        raw = [
            ("$" + "".join(f"[{part}]" if isinstance(part, int) else f".{part}" for part in error.absolute_path), error.message)
            for error in errors
        ]
    return [
        {"node": node_id, "code": "schema_violation", "detail": f"{path}: {detail}"}
        for path, detail in raw
    ]


def _scalar(raw: str) -> Any:
    value = raw.strip()
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        if (value.startswith("'") and value.endswith("'")) or (value.startswith('"') and value.endswith('"')):
            return value[1:-1]
        return value


def frontmatter_of(path: Path) -> dict[str, Any]:
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError as exc:
        raise ContractError(f"cannot read artifact {path}: {exc}") from exc
    if not lines or lines[0].strip() != "---":
        raise ContractError(f"artifact has no YAML frontmatter: {path}")
    result: dict[str, Any] = {}
    for line in lines[1:]:
        if line.strip() == "---":
            return result
        match = re.match(r"^([A-Za-z_][A-Za-z0-9_-]*):(?:\s*(.*))?$", line)
        if match:
            result[match.group(1)] = _scalar(match.group(2) or "")
    raise ContractError(f"artifact frontmatter is not terminated: {path}")


def _repo_root_for(graph: Path, explicit: str | None) -> Path:
    if explicit:
        root = Path(explicit).expanduser().resolve(strict=True)
        contained(graph, root)
        return root
    resolved = graph.resolve(strict=True)
    for parent in resolved.parents:
        if parent.name == ".dev-graph":
            return parent.parent
    raise ContractError("--repo-root is required when --graph is outside the canonical .dev-graph tree")


def artifact_findings(
    nodes: list[dict[str, Any]], repo_root: Path | None, template_contract: dict[str, Any]
) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    required_frontmatter = set((template_contract.get("common_frontmatter") or {}).get("required") or [])
    for index, node in enumerate(nodes):
        node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
        kind = node.get("artifact_kind", node.get("kind"))
        raw_path = node.get("file_path")
        if kind in ROOT_BY_KIND and isinstance(raw_path, str):
            logical = PurePosixPath(raw_path)
            if logical.is_absolute() or ".." in logical.parts or not logical.parts or logical.parts[0] != ROOT_BY_KIND[kind]:
                findings.append({"node": node_id, "code": "path_parity_error", "detail": f"{kind} must be under {ROOT_BY_KIND[kind]}/"})
                continue
        if repo_root is None or not isinstance(raw_path, str):
            continue
        candidate = repo_root / raw_path
        try:
            # Missing canonical artifacts are readiness gaps, not containment
            # failures.  Resolve without requiring existence, then let the
            # is_file check below classify the missing artifact explicitly.
            artifact = contained(candidate, repo_root, must_exist=False)
        except (ContractError, OSError) as exc:
            findings.append({"node": node_id, "code": "artifact_path_invalid", "detail": str(exc)})
            continue
        if not artifact.is_file():
            findings.append({"node": node_id, "code": "artifact_missing", "detail": raw_path})
            continue
        try:
            frontmatter = frontmatter_of(artifact)
        except ContractError as exc:
            findings.append({"node": node_id, "code": "frontmatter_invalid", "detail": str(exc)})
            continue
        for key in sorted(required_frontmatter - set(frontmatter)):
            findings.append({"node": node_id, "code": "frontmatter_missing", "detail": key})
        for key in ("graph_node_id", "artifact_kind", "file_path", "template_id", "template_version"):
            if key in node and frontmatter.get(key) != node.get(key):
                findings.append({"node": node_id, "code": "frontmatter_parity_error", "detail": key})
    return findings


def domain_findings(nodes: list[dict[str, Any]]) -> list[dict[str, str]]:
    findings: list[dict[str, str]] = []
    ids: list[str] = []
    by_id: dict[str, dict[str, Any]] = {}
    for index, node in enumerate(nodes):
        node_id = node.get("graph_node_id") or node.get("id")
        loc = str(node_id or f"nodes[{index}]")
        if not isinstance(node_id, str) or not node_id:
            findings.append({"node": loc, "code": "missing_id", "detail": "graph_node_id required"})
            continue
        ids.append(node_id)
        by_id[node_id] = node
        kind = node.get("artifact_kind", node.get("kind"))
        if kind is not None and kind not in ROOT_BY_KIND:
            findings.append({"node": loc, "code": "invalid_kind", "detail": str(kind)})
        if node.get("status") not in {"draft", "active", "blocked", "done", "closed", "tombstoned"}:
            findings.append({"node": loc, "code": "invalid_status", "detail": str(node.get("status"))})
        dependencies = node.get("depends_on", [])
        if not isinstance(dependencies, list) or any(not isinstance(value, str) for value in dependencies):
            findings.append({"node": loc, "code": "invalid_dependencies", "detail": "depends_on must be string[]"})
        if node.get("tracker_binding") == "beads" and (node.get("github_publication") or {}).get("mode") != "local_only":
            findings.append({"node": loc, "code": "beads_publication", "detail": "beads requires local_only"})
        if node.get("tracker_binding") == "github" and node.get("beads_linkage") is not None:
            findings.append({"node": loc, "code": "binding_collision", "detail": "github cannot have beads_linkage"})
        if node.get("status") == "active":
            readiness = (node.get("implementation_readiness") or {}).get("status")
            if node.get("confirmation_status") != "confirmed" or node.get("evaluation_status") != "pass" or readiness != "complete":
                findings.append({"node": loc, "code": "active_not_ready", "detail": "active requires confirmed/pass/complete"})
        if node.get("tracker_binding") == "repo-config-default":
            findings.append({"node": loc, "code": "unresolved_tracker_binding", "detail": "durable graph cannot retain repo-config-default"})
    for duplicate, count in Counter(ids).items():
        if count > 1:
            findings.append({"node": duplicate, "code": "duplicate_id", "detail": str(count)})
    reference_fields = ("depends_on", "related_nodes", "architecture_refs")
    for index, node in enumerate(nodes):
        node_id = str(node.get("graph_node_id") or node.get("id") or f"nodes[{index}]")
        for field in reference_fields:
            for reference in node.get(field, []) if isinstance(node.get(field, []), list) else []:
                if reference not in by_id:
                    code = "dangling_dependency" if field == "depends_on" else "dangling_reference"
                    findings.append({"node": node_id, "code": code, "detail": f"{field}:{reference}"})
        parent = node.get("parent_feature")
        if isinstance(parent, str) and parent not in by_id:
            findings.append({"node": node_id, "code": "dangling_reference", "detail": f"parent_feature:{parent}"})

    state: dict[str, int] = {}

    def visit(node_id: str) -> None:
        if state.get(node_id) == 1:
            findings.append({"node": node_id, "code": "dependency_cycle", "detail": node_id})
            return
        if state.get(node_id) == 2:
            return
        state[node_id] = 1
        dependencies = by_id[node_id].get("depends_on", [])
        for dependency in dependencies if isinstance(dependencies, list) else []:
            if dependency in by_id:
                visit(dependency)
        state[node_id] = 2

    for node_id in by_id:
        visit(node_id)

    children: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for node in nodes:
        if isinstance(node.get("parent_feature"), str):
            children[node["parent_feature"]].append(node)
    order = {phase: int(phase[1:]) for phase in PHASES}
    for feature_id, feature in ((node_id, node) for node_id, node in by_id.items() if node.get("artifact_kind") == "feature"):
        members = children.get(feature_id, [])
        if members or feature.get("status") == "done":
            packages = {member.get("feature_package_id") for member in members}
            phases = [member.get("phase_ref") for member in members]
            if packages == {None} or len(packages) != 1 or set(phases) != PHASES or len(members) != 13:
                findings.append({"node": feature_id, "code": "feature_package_not_exact_13", "detail": f"count={len(members)} phases={sorted(str(value) for value in set(phases))}"})
        for child in members:
            current = order.get(child.get("phase_ref"), 0)
            for dependency in child.get("depends_on", []):
                target = by_id.get(dependency, {})
                if target.get("parent_feature") == feature_id and order.get(target.get("phase_ref"), 0) >= current:
                    findings.append({"node": str(child.get("graph_node_id") or child.get("id") or "?"), "code": "non_forward_phase_dependency", "detail": dependency})
        if feature.get("status") == "done":
            if any(member.get("status") != "done" for member in members):
                findings.append({"node": feature_id, "code": "premature_feature_done", "detail": "all 13 children must be done"})
            for phase in {"P07", "P10", "P11"}:
                child = next((member for member in members if member.get("phase_ref") == phase), {})
                if not (child.get("completion_evidence") or {}).get("evidence_refs"):
                    findings.append({"node": feature_id, "code": "feature_evidence_missing", "detail": phase})
    return findings


def validate(
    nodes: list[dict[str, Any]], schema: dict[str, Any] | None = None,
    *, repo_root: Path | None = None, template_contract: dict[str, Any] | None = None,
) -> list[dict[str, str]]:
    canonical_schema = schema or load_json(SCHEMA_PATH)
    if not isinstance(canonical_schema, dict):
        raise ContractError(f"canonical graph schema must be an object: {SCHEMA_PATH}")
    contract = template_contract or load_json(TEMPLATE_CONTRACT_PATH)
    if not isinstance(contract, dict):
        raise ContractError(f"template contract must be an object: {TEMPLATE_CONTRACT_PATH}")
    findings = [item for index, node in enumerate(nodes) for item in schema_findings(node, canonical_schema, index)]
    findings.extend(domain_findings(nodes))
    findings.extend(artifact_findings(nodes, repo_root, contract))
    return sorted(findings, key=lambda item: (item["node"], item["code"], item["detail"]))


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--graph", required=True)
    parser.add_argument("--repo-root")
    args = parser.parse_args()
    graph = Path(args.graph).expanduser().resolve(strict=True)
    nodes = nodes_of(load_json(graph))
    violations = validate(nodes, repo_root=_repo_root_for(graph, args.repo_root))
    missing = sorted({
        item["detail"] for item in violations
        if item["code"] in {"frontmatter_missing", "artifact_missing"}
        or (item["code"] == "schema_violation" and "required property" in item["detail"])
    })
    dump({
        "valid": not violations,
        "implementation_readiness": "complete" if not violations else "incomplete",
        "missing_sections": missing,
        "schema": str(SCHEMA_PATH),
        "violations": violations,
    })
    return 0 if not violations else 1


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(2)

#!/usr/bin/env python3
# /// script
# name: build-external-mutation-guard
# purpose: Bind an external mutation to a preview receipt, an actual UserPromptSubmit confirmation or intent event, and an exact argv consumer.
# inputs:
#   - argv: preview | hook-confirm | authorize | authorize-intent | cancel | execute | pretool
#   - stdin: Claude hook JSON for hook-confirm/pretool
# outputs:
#   - stdout: sealed receipt metadata or official PreToolUse deny JSON
# contexts: [A, C, E]
# network: false
# write-scope: project/.artifact-delivery/external-mutation only; execute runs only the argv bound by receipts
# dependencies: []
# requires-python: ">=3.10"
# ///
"""Executable preview -> user confirmation -> authorization -> mutation guard."""
from __future__ import annotations

import argparse
import hashlib
import hmac
import json
import os
import re
import secrets
import shlex
import subprocess
import sys
import tempfile
import time
import uuid
from pathlib import Path
from typing import Any


CONTRACT_ID = "external-mutation-guard-v1"
SCHEMA_VERSION = 1
STATE_REL = Path(".artifact-delivery/external-mutation")
KEY_NAME = ".guard-key"
TTL_SECONDS = 900
CONFIRM_RE = re.compile(r"^CONFIRM EXTERNAL MUTATION ([0-9A-F]{24})$")
INTENT_KIND = "intent"
# 人間の自然文リクエストで自動承認してよい操作クラス。取り消し可能な範囲だけを列挙する。
AUTO_GRANT_CLASSES = frozenset({"github-pr-write", "github-issue-write", "beads-issue-write"})
GH_PR_AUTO_VERBS = frozenset({"create", "edit", "comment", "ready"})
GH_ISSUE_AUTO_VERBS = frozenset({"create", "edit", "comment", "close", "reopen"})
BD_AUTO_VERBS = frozenset({"create", "update", "close", "reopen"})
# 自然文の意図宣言。UserPromptSubmit の実イベントでのみ評価され、付与クラスを限定する。
INTENT_PATTERNS: tuple[tuple[re.Pattern[str], frozenset[str]], ...] = (
    (
        re.compile(
            # \bPR\b は使えない: Python の \w は CJK を含むため "PRを出して" で
            # 単語境界が成立せず落ちる。境界判定を ASCII 英字だけに限定する。
            r"(?:プルリク(?:エスト)?|プル\s*リクエスト|pull\s*request|(?<![A-Za-z])PR(?![A-Za-z]))"
            r"[^\n]{0,40}?"
            r"(?:出し|出す|出せ|作成|作って|作る|上げ|開い|投げ|送っ|create|open|raise|submit)",
            re.I,
        ),
        frozenset({"github-pr-write"}),
    ),
    (
        re.compile(
            r"(?:issue|イシュー|課題|チケット)"
            r"[^\n]{0,40}?"
            r"(?:立て|作成|作って|作る|閉じ|クローズ|更新|create|close|reopen|update)",
            re.I,
        ),
        frozenset({"github-issue-write", "beads-issue-write"}),
    ),
)
ENTRYPOINT_RE = re.compile(r"^plugin:[a-z0-9][a-z0-9-]*/skills/[a-z0-9][a-z0-9-]*/SKILL\.md$")
PYTHON_RE = re.compile(r"^python3(?:\.\d+)?$")
RUNNER_NAME = "build-external-mutation-guard.py"
SHELL_CONTROL_TOKENS = frozenset({";", "&", "&&", "|", "||", "<", ">", "<<", ">>", "(", ")"})
CANONICAL_ACTION_FLAGS = {
    "preview": frozenset(
        {
            "--project-root",
            "--entrypoint-ref",
            "--target-scope",
            "--diff-summary",
            "--side-effect-summary",
            "--command-json",
        }
    ),
    "authorize": frozenset(
        {"--project-root", "--preview-receipt", "--confirmation-receipt"}
    ),
    "authorize-intent": frozenset(
        {"--project-root", "--preview-receipt", "--intent-receipt"}
    ),
    "execute": frozenset(
        {"--project-root", "--authorization-receipt", "--command-json"}
    ),
    "cancel": frozenset({"--project-root", "--preview-receipt"}),
}
DIRECT_MUTATION_PATTERNS = (
    re.compile(r"\bcurl\b[^\n]*(?:-X|--request)\s*(?:POST|PUT|PATCH|DELETE)\b", re.I),
    re.compile(r"\bcurl\b[^\n]*(?:--data(?:-raw|-binary)?|-d)\s", re.I),
    re.compile(r"\bgh\s+(?:issue|pr)\s+(?:create|edit|close|reopen|merge|comment)\b", re.I),
    re.compile(r"\bgh\s+api\b[^\n]*(?:-X|--method)\s*(?:POST|PUT|PATCH|DELETE)\b", re.I),
    re.compile(r"\bbd\s+(?:create|update|close|reopen|delete|dep\s+add)\b", re.I),
    re.compile(r"\b(?:send-campaign|publish-notion-page|notion-submit-improvement)\.py\b", re.I),
    re.compile(r"\bgh-bridge\.py\b[^\n]*\bapply\b", re.I),
    re.compile(r"\bintake_publish_pipeline\.py\b", re.I),
    re.compile(r"\bsetup-send-log-db\.py\b[^\n]*--apply\b", re.I),
)


class GuardError(ValueError):
    """Fail-closed receipt or execution contract violation."""


def _compact(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _ordered_output(value: dict[str, Any]) -> str:
    """Preserve human-review field order; receipt canonicalization remains sorted."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _sha256_file(path: Path) -> str:
    return _sha256_bytes(path.read_bytes())


def _command(value: str) -> list[str]:
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError as exc:
        raise GuardError(f"command-json is invalid JSON: {exc}") from exc
    if (
        not isinstance(parsed, list)
        or not parsed
        or not all(isinstance(item, str) and item for item in parsed)
    ):
        raise GuardError("command-json must be a non-empty JSON string array")
    return parsed


def _command_sha256(argv: list[str]) -> str:
    return _sha256_bytes(_compact(argv).encode("utf-8"))


def _action_class(argv: list[str]) -> str | None:
    """Classify argv into an auto-grantable class; unknown or irreversible argv stays None."""
    program = Path(argv[0]).name
    rest = argv[1:]
    if program == "gh" and len(rest) >= 2:
        surface, verb = rest[0], rest[1]
        if surface == "pr" and verb in GH_PR_AUTO_VERBS:
            return "github-pr-write"
        if surface == "issue" and verb in GH_ISSUE_AUTO_VERBS:
            return "github-issue-write"
        return None
    if program == "bd" and rest:
        if rest[0] in BD_AUTO_VERBS:
            return "beads-issue-write"
        if rest[0] == "dep" and len(rest) >= 2 and rest[1] == "add":
            return "beads-issue-write"
    return None


def _intent_classes(prompt: str) -> frozenset[str]:
    granted: set[str] = set()
    for pattern, classes in INTENT_PATTERNS:
        if pattern.search(prompt):
            granted |= set(classes)
    return frozenset(granted & AUTO_GRANT_CLASSES)


def _review_text(value: str, *, name: str) -> str:
    normalized = " ".join(value.split())
    if not normalized:
        raise GuardError(f"{name} must be non-empty")
    if len(normalized.encode("utf-8")) > 2048:
        raise GuardError(f"{name} exceeds 2048 UTF-8 bytes")
    return normalized


def _project_root(value: str) -> Path:
    try:
        root = Path(value).expanduser().resolve(strict=True)
    except OSError as exc:
        raise GuardError(f"project root does not exist: {value}") from exc
    if not root.is_dir():
        raise GuardError(f"project root is not a directory: {root}")
    return root


def _state_dir(root: Path, *, create: bool) -> Path:
    state = root / STATE_REL
    if create:
        state.mkdir(parents=True, exist_ok=True)
        os.chmod(state, 0o700)
    try:
        resolved = state.resolve(strict=True)
    except OSError as exc:
        raise GuardError(f"guard state is unavailable: {state}") from exc
    try:
        resolved.relative_to(root)
    except ValueError as exc:
        raise GuardError("guard state escapes project root") from exc
    return resolved


def _key(state: Path, *, create: bool) -> bytes:
    path = state / KEY_NAME
    if create and not path.exists():
        try:
            descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            pass
        else:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(secrets.token_bytes(32))
    try:
        value = path.read_bytes()
    except OSError as exc:
        raise GuardError("guard key is unavailable") from exc
    if len(value) != 32:
        raise GuardError("guard key is invalid")
    return value


def _seal(body: dict[str, Any], key: bytes) -> str:
    unsigned = {name: value for name, value in body.items() if name != "seal"}
    return hmac.new(key, _compact(unsigned).encode("utf-8"), hashlib.sha256).hexdigest()


def _write_receipt(state: Path, name: str, body: dict[str, Any], key: bytes) -> Path:
    destination = state / name
    if destination.exists():
        raise GuardError(f"receipt already exists: {destination.name}")
    document = {**body, "seal": _seal(body, key)}
    descriptor, temporary = tempfile.mkstemp(prefix=f".{name}.", dir=state)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(document, handle, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, 0o600)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return destination


def _write_once(state: Path, name: str, body: dict[str, Any], key: bytes) -> Path:
    """Atomically create a sealed claim; an existing claim is never replaced."""
    destination = state / name
    document = {**body, "seal": _seal(body, key)}
    try:
        descriptor = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError as exc:
        raise GuardError("preview and confirmation were already consumed by authorization") from exc
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(document, handle, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
    except BaseException:
        # A partially written O_EXCL claim remains fail-closed and cannot be replayed.
        raise
    return destination


def _receipt(state: Path, raw_path: str, expected_kind: str, key: bytes) -> tuple[Path, dict[str, Any]]:
    try:
        path = Path(raw_path).expanduser().resolve(strict=True)
        path.relative_to(state)
    except (OSError, ValueError) as exc:
        raise GuardError("receipt path is outside canonical guard state") from exc
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise GuardError(f"receipt is unreadable: {path}") from exc
    if not isinstance(document, dict):
        raise GuardError("receipt root must be an object")
    if document.get("contract_id") != CONTRACT_ID or document.get("schema_version") != SCHEMA_VERSION:
        raise GuardError("receipt contract identity drift")
    if document.get("kind") != expected_kind:
        raise GuardError(f"expected {expected_kind} receipt")
    seal = document.get("seal")
    if not isinstance(seal, str) or not hmac.compare_digest(seal, _seal(document, key)):
        raise GuardError("receipt seal mismatch; receipt may be tampered")
    expires_at = document.get("expires_at")
    if not isinstance(expires_at, int) or expires_at < int(time.time()):
        raise GuardError("receipt expired")
    return path, document


def _base(kind: str, receipt_id: str, *, now: int) -> dict[str, Any]:
    return {
        "schema_version": SCHEMA_VERSION,
        "contract_id": CONTRACT_ID,
        "kind": kind,
        "receipt_id": receipt_id,
        "issued_at": now,
        # Second resolution cannot order two receipts issued inside the same second.
        "issued_at_ns": time.time_ns(),
        "expires_at": now + TTL_SECONDS,
    }


def _issued_ns(receipt: dict[str, Any]) -> int:
    value = receipt.get("issued_at_ns")
    if isinstance(value, int):
        return value
    return int(receipt["issued_at"]) * 1_000_000_000


def preview(args: argparse.Namespace) -> dict[str, Any]:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=True)
    key = _key(state, create=True)
    argv = _command(args.command_json)
    if not ENTRYPOINT_RE.fullmatch(args.entrypoint_ref):
        raise GuardError("entrypoint-ref must be a canonical plugin SKILL.md ref")
    target_scope = _review_text(args.target_scope, name="target-scope")
    diff_summary = _review_text(args.diff_summary, name="diff-summary")
    side_effect_summary = _review_text(args.side_effect_summary, name="side-effect-summary")
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    challenge = secrets.token_hex(12).upper()
    action_class = _action_class(argv)
    body = {
        **_base("preview", receipt_id, now=now),
        "entrypoint_ref": args.entrypoint_ref,
        "target_scope": target_scope,
        "command_argv": argv,
        "command_sha256": _command_sha256(argv),
        "action_class": action_class,
        "diff_summary": diff_summary,
        "side_effect_summary": side_effect_summary,
        "challenge_sha256": _sha256_bytes(challenge.encode("ascii")),
        "status": "pending-user-confirmation",
    }
    path = _write_receipt(state, f"preview-{receipt_id}.json", body, key)
    auto_grantable = action_class in AUTO_GRANT_CLASSES
    instruction = f"Reply exactly: CONFIRM EXTERNAL MUTATION {challenge}"
    if auto_grantable:
        instruction = (
            f"A live intent grant covering {action_class} authorizes this via authorize-intent; "
            f"otherwise reply exactly: CONFIRM EXTERNAL MUTATION {challenge}"
        )
    return {
        "contract_id": CONTRACT_ID,
        "status": "preview-created",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "target_scope": target_scope,
        "command_argv": argv,
        "action_class": action_class,
        "auto_grantable": auto_grantable,
        "diff_summary": diff_summary,
        "side_effect_summary": side_effect_summary,
        "challenge": challenge,
        "user_instruction": instruction,
    }


def _read_hook_payload() -> dict[str, Any]:
    try:
        value = json.loads(sys.stdin.read() or "{}")
    except json.JSONDecodeError:
        return {}
    return value if isinstance(value, dict) else {}


def hook_confirm() -> dict[str, Any] | None:
    payload = _read_hook_payload()
    if payload.get("hook_event_name") not in {None, "UserPromptSubmit"}:
        return None
    prompt = payload.get("prompt")
    cwd = payload.get("cwd")
    session_id = payload.get("session_id")
    if not isinstance(prompt, str) or not isinstance(cwd, str) or not isinstance(session_id, str):
        return None
    stripped = prompt.strip()
    root = _project_root(cwd)
    matched = CONFIRM_RE.fullmatch(stripped)
    if matched is not None:
        return _confirm_challenge(root, stripped, session_id, matched.group(1))
    granted = _intent_classes(stripped)
    if not granted:
        return None
    return _grant_intent(root, stripped, session_id, granted)


def _user_event_id(session_id: str, prompt: str) -> str:
    return _sha256_bytes(f"{session_id}\0{prompt}".encode("utf-8"))


def _confirm_challenge(
    root: Path, prompt: str, session_id: str, challenge: str
) -> dict[str, Any]:
    """Bind a typed challenge to its single live preview.

    A challenge that matches no live preview creates no receipt and does not block the
    prompt: refusing the user's message buys no safety and strands the session.
    """
    unmatched = {
        "contract_id": CONTRACT_ID,
        "status": "confirmation-unmatched",
        "detail": "no live preview matches this challenge; it may have expired or been consumed",
    }
    try:
        state = _state_dir(root, create=False)
        key = _key(state, create=False)
    except GuardError:
        return unmatched
    challenge_hash = _sha256_bytes(challenge.encode("ascii"))
    candidates: list[tuple[Path, dict[str, Any]]] = []
    for path in sorted(state.glob("preview-*.json")):
        try:
            loaded_path, receipt = _receipt(state, str(path), "preview", key)
        except GuardError:
            continue
        if receipt.get("challenge_sha256") == challenge_hash:
            candidates.append((loaded_path, receipt))
    if len(candidates) != 1:
        return unmatched
    preview_path, preview_receipt = candidates[0]
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    body = {
        **_base("confirmation", receipt_id, now=now),
        "preview_receipt_id": preview_receipt["receipt_id"],
        "preview_receipt_sha256": _sha256_file(preview_path),
        "producer": "claude-code-user-prompt-submit",
        "user_event_id": _user_event_id(session_id, prompt),
        "decision": "confirm",
    }
    path = _write_receipt(state, f"confirmation-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "confirmation-created",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
    }


def _grant_intent(
    root: Path, prompt: str, session_id: str, granted: frozenset[str]
) -> dict[str, Any]:
    """Seal a single-use grant proving a human asked for this class of mutation."""
    state = _state_dir(root, create=True)
    key = _key(state, create=True)
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    body = {
        **_base(INTENT_KIND, receipt_id, now=now),
        "granted_classes": sorted(granted),
        "producer": "claude-code-user-prompt-submit",
        "user_event_id": _user_event_id(session_id, prompt),
        "prompt_excerpt": " ".join(prompt.split())[:200],
        "decision": "confirm-by-intent",
    }
    path = _write_receipt(state, f"{INTENT_KIND}-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "intent-granted",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "granted_classes": sorted(granted),
    }


def authorize(args: argparse.Namespace) -> dict[str, Any]:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    confirmation_path, confirmation_receipt = _receipt(
        state, args.confirmation_receipt, "confirmation", key
    )
    if (
        confirmation_receipt.get("preview_receipt_id") != preview_receipt["receipt_id"]
        or confirmation_receipt.get("preview_receipt_sha256") != _sha256_file(preview_path)
    ):
        raise GuardError("confirmation receipt is not bound to the supplied preview receipt")
    return _seal_authorization(
        state,
        key,
        preview_path,
        preview_receipt,
        confirmation_path,
        confirmation_receipt,
        confirmation_kind="confirmation",
    )


def authorize_intent(args: argparse.Namespace) -> dict[str, Any]:
    """Authorize an auto-grantable preview against a live human intent grant."""
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    intent_path, intent_receipt = _receipt(state, args.intent_receipt, INTENT_KIND, key)
    action_class = preview_receipt.get("action_class")
    if action_class not in AUTO_GRANT_CLASSES:
        raise GuardError(
            "preview action class is not auto-grantable; use the typed confirmation flow"
        )
    granted = intent_receipt.get("granted_classes")
    if not isinstance(granted, list) or action_class not in granted:
        raise GuardError("intent grant does not cover the preview action class")
    if _issued_ns(intent_receipt) > _issued_ns(preview_receipt):
        raise GuardError("preview predates the intent grant; the user request must come first")
    _write_once(
        state,
        f"intent-claim-{intent_receipt['receipt_id']}.json",
        {
            "contract_id": CONTRACT_ID,
            "schema_version": SCHEMA_VERSION,
            "kind": "intent-claim",
            "intent_receipt_id": intent_receipt["receipt_id"],
            "intent_receipt_sha256": _sha256_file(intent_path),
            "preview_receipt_id": preview_receipt["receipt_id"],
            "claimed_at": int(time.time()),
        },
        key,
    )
    return _seal_authorization(
        state,
        key,
        preview_path,
        preview_receipt,
        intent_path,
        intent_receipt,
        confirmation_kind=INTENT_KIND,
    )


def _seal_authorization(
    state: Path,
    key: bytes,
    preview_path: Path,
    preview_receipt: dict[str, Any],
    confirmation_path: Path,
    confirmation_receipt: dict[str, Any],
    *,
    confirmation_kind: str,
) -> dict[str, Any]:
    now = int(time.time())
    preview_sha256 = _sha256_file(preview_path)
    confirmation_sha256 = _sha256_file(confirmation_path)
    _write_once(
        state,
        f"authorization-claim-preview-{preview_receipt['receipt_id']}.json",
        {
            "contract_id": CONTRACT_ID,
            "schema_version": SCHEMA_VERSION,
            "kind": "authorization-claim",
            "preview_receipt_id": preview_receipt["receipt_id"],
            "preview_receipt_sha256": preview_sha256,
            "confirmation_receipt_id": confirmation_receipt["receipt_id"],
            "confirmation_receipt_sha256": confirmation_sha256,
            "claimed_at": now,
        },
        key,
    )
    receipt_id = uuid.uuid4().hex
    body = {
        **_base("authorization", receipt_id, now=now),
        "preview_receipt_id": preview_receipt["receipt_id"],
        "preview_receipt_sha256": preview_sha256,
        "confirmation_receipt_id": confirmation_receipt["receipt_id"],
        "confirmation_receipt_sha256": confirmation_sha256,
        "confirmation_receipt_kind": confirmation_kind,
        "entrypoint_ref": preview_receipt["entrypoint_ref"],
        "target_scope": preview_receipt["target_scope"],
        "command_sha256": preview_receipt["command_sha256"],
        "status": "authorized-once",
    }
    path = _write_receipt(state, f"authorization-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "authorized",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "confirmation_receipt_kind": confirmation_kind,
    }


def cancel(args: argparse.Namespace) -> dict[str, Any]:
    """Resolve a preview without executing it so pending guard context stops blocking Bash."""
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    path = _write_receipt(
        state,
        f"cancellation-preview-{preview_receipt['receipt_id']}.json",
        {
            **_base("cancellation", receipt_id, now=now),
            "preview_receipt_id": preview_receipt["receipt_id"],
            "preview_receipt_sha256": _sha256_file(preview_path),
            "status": "cancelled",
        },
        key,
    )
    return {
        "contract_id": CONTRACT_ID,
        "status": "cancelled",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
    }


def execute(args: argparse.Namespace) -> int:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    authorization_path, authorization = _receipt(
        state, args.authorization_receipt, "authorization", key
    )
    argv = _command(args.command_json)
    if authorization.get("command_sha256") != _command_sha256(argv):
        raise GuardError("execute command digest differs from authorized preview")
    preview_path = state / f"preview-{authorization['preview_receipt_id']}.json"
    confirmation_kind = authorization.get("confirmation_receipt_kind", "confirmation")
    if confirmation_kind not in {"confirmation", INTENT_KIND}:
        raise GuardError("authorization names an unknown confirmation receipt kind")
    confirmation_path = (
        state / f"{confirmation_kind}-{authorization['confirmation_receipt_id']}.json"
    )
    if _sha256_file(preview_path) != authorization.get("preview_receipt_sha256"):
        raise GuardError("preview receipt changed after authorization")
    if _sha256_file(confirmation_path) != authorization.get("confirmation_receipt_sha256"):
        raise GuardError("confirmation receipt changed after authorization")
    consumed = state / f"consumed-{authorization['receipt_id']}.json"
    try:
        descriptor = os.open(consumed, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError as exc:
        raise GuardError("authorization receipt was already consumed") from exc
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        json.dump(
            {
                "authorization_receipt_sha256": _sha256_file(authorization_path),
                "consumed_at": int(time.time()),
            },
            handle,
            sort_keys=True,
        )
        handle.write("\n")
    completed = subprocess.run(argv, cwd=root, text=True, capture_output=True, shell=False, check=False)
    if completed.stdout:
        sys.stdout.write(completed.stdout)
    if completed.stderr:
        sys.stderr.write(completed.stderr)
    if completed.returncode == 0:
        now = int(time.time())
        completion_id = uuid.uuid4().hex
        _write_receipt(
            state,
            f"completion-preview-{authorization['preview_receipt_id']}.json",
            {
                **_base("completion", completion_id, now=now),
                "preview_receipt_id": authorization["preview_receipt_id"],
                "authorization_receipt_id": authorization["receipt_id"],
                "authorization_receipt_sha256": _sha256_file(authorization_path),
                "status": "executed-successfully",
            },
            key,
        )
    return completed.returncode


def _canonical_guard_action(command: str) -> str | None:
    """Return the action only when the entire shell command is one canonical guard call."""
    try:
        lexer = shlex.shlex(command, posix=True, punctuation_chars=";&|<>()")
        lexer.whitespace_split = True
        lexer.commenters = ""
        tokens = list(lexer)
    except ValueError:
        return None
    if len(tokens) < 3 or any(token in SHELL_CONTROL_TOKENS for token in tokens):
        return None
    if not PYTHON_RE.fullmatch(Path(tokens[0]).name) or Path(tokens[1]).name != RUNNER_NAME:
        return None
    action = tokens[2]
    expected_flags = CANONICAL_ACTION_FLAGS.get(action)
    rest = tokens[3:]
    if expected_flags is None or len(rest) != 2 * len(expected_flags):
        return None
    supplied: dict[str, str] = {}
    for index in range(0, len(rest), 2):
        flag, value = rest[index : index + 2]
        if flag not in expected_flags or flag in supplied or not value:
            return None
        supplied[flag] = value
    return action if set(supplied) == expected_flags else None


def _has_pending_guard_context(payload: dict[str, Any]) -> bool:
    cwd = payload.get("cwd")
    if not isinstance(cwd, str) or not cwd:
        return False
    try:
        root = _project_root(cwd)
    except GuardError:
        return False
    if not (root / STATE_REL).exists():
        return False
    try:
        state = _state_dir(root, create=False)
        key = _key(state, create=False)
    except GuardError:
        # Existing but unreadable/non-canonical guard state cannot prove safety.
        return True
    for preview_path in sorted(state.glob("preview-*.json")):
        try:
            _, preview_receipt = _receipt(state, str(preview_path), "preview", key)
        except GuardError as exc:
            if "expired" in str(exc):
                continue
            # A malformed receipt inside canonical state cannot safely prove no pending mutation.
            return True
        resolution: tuple[str, Path, str] | None = None
        for kind, terminal_status in (
            ("completion", "executed-successfully"),
            ("cancellation", "cancelled"),
        ):
            candidate = state / f"{kind}-preview-{preview_receipt['receipt_id']}.json"
            if candidate.is_file():
                resolution = (kind, candidate, terminal_status)
                break
        if resolution is None:
            return True
        kind, resolution_path, terminal_status = resolution
        try:
            _, resolved = _receipt(state, str(resolution_path), kind, key)
        except GuardError:
            return True
        if (
            resolved.get("preview_receipt_id") != preview_receipt["receipt_id"]
            or resolved.get("status") != terminal_status
        ):
            return True
    return False


def _deny(reason: str) -> dict[str, Any]:
    return {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }


def pretool() -> dict[str, Any] | None:
    payload = _read_hook_payload()
    if payload.get("hook_event_name") not in {None, "PreToolUse"}:
        return None
    if payload.get("tool_name") != "Bash":
        return None
    tool_input = payload.get("tool_input")
    command = tool_input.get("command") if isinstance(tool_input, dict) else None
    if not isinstance(command, str) or not command.strip():
        return None
    if _canonical_guard_action(command) is not None:
        return None
    if RUNNER_NAME in command:
        return _deny(
            "Malformed central guard invocation is blocked: the full Bash command must be "
            "exactly one canonical preview, authorize, or execute call with no shell operators."
        )
    if _has_pending_guard_context(payload):
        return _deny(
            "A pending guard context blocks non-canonical Bash execution until its exact "
            "preview -> confirmation -> authorize -> execute flow completes or expires."
        )
    if not any(pattern.search(command) for pattern in DIRECT_MUTATION_PATTERNS):
        return None
    return _deny(
        "Direct external mutation is blocked. Use build-external-mutation-guard.py "
        "preview -> user confirmation -> authorize -> execute."
    )


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="action", required=True)
    preview_parser = commands.add_parser("preview")
    preview_parser.add_argument("--project-root", required=True)
    preview_parser.add_argument("--entrypoint-ref", required=True)
    preview_parser.add_argument("--target-scope", required=True)
    preview_parser.add_argument("--diff-summary", required=True)
    preview_parser.add_argument("--side-effect-summary", required=True)
    preview_parser.add_argument("--command-json", required=True)
    commands.add_parser("hook-confirm")
    authorize_parser = commands.add_parser("authorize")
    authorize_parser.add_argument("--project-root", required=True)
    authorize_parser.add_argument("--preview-receipt", required=True)
    authorize_parser.add_argument("--confirmation-receipt", required=True)
    authorize_intent_parser = commands.add_parser("authorize-intent")
    authorize_intent_parser.add_argument("--project-root", required=True)
    authorize_intent_parser.add_argument("--preview-receipt", required=True)
    authorize_intent_parser.add_argument("--intent-receipt", required=True)
    cancel_parser = commands.add_parser("cancel")
    cancel_parser.add_argument("--project-root", required=True)
    cancel_parser.add_argument("--preview-receipt", required=True)
    execute_parser = commands.add_parser("execute")
    execute_parser.add_argument("--project-root", required=True)
    execute_parser.add_argument("--authorization-receipt", required=True)
    execute_parser.add_argument("--command-json", required=True)
    commands.add_parser("pretool")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.action == "preview":
            print(_ordered_output(preview(args)))
            return 0
        if args.action == "hook-confirm":
            result = hook_confirm()
            if result is not None:
                print(
                    _compact(
                        {
                            "continue": True,
                            "suppressOutput": True,
                            "hookSpecificOutput": {
                                "hookEventName": "UserPromptSubmit",
                                "additionalContext": "[external-mutation-confirmation]\n"
                                + _compact(result),
                            },
                        }
                    )
                )
            return 0
        if args.action == "authorize":
            print(_compact(authorize(args)))
            return 0
        if args.action == "authorize-intent":
            print(_compact(authorize_intent(args)))
            return 0
        if args.action == "cancel":
            print(_compact(cancel(args)))
            return 0
        if args.action == "execute":
            return execute(args)
        result = pretool()
        if result is not None:
            print(_compact(result))
        return 0
    except (GuardError, OSError, KeyError, subprocess.SubprocessError) as exc:
        print(f"EXTERNAL_MUTATION_GUARD_ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# /// script
# name: build-external-mutation-guard
# purpose: Bind an external mutation to a preview receipt, an actual UserPromptSubmit confirmation or intent event, and an exact argv consumer.
# inputs:
#   - argv: preview | hook-confirm | authorize | authorize-intent | cancel | execute | pretool
#   - stdin: Claude hook JSON for hook-confirm/pretool
# outputs:
#   - stdout: sealed receipt metadata or official PreToolUse deny JSON
# contexts: [A, C, E]
# network: false
# write-scope: project/.artifact-delivery/external-mutation only; execute runs only the argv bound by receipts
# dependencies: []
# requires-python: ">=3.10"
# ///
"""Executable preview -> user confirmation -> authorization -> mutation guard."""
from __future__ import annotations

import argparse
import hashlib
import hmac
import json
import os
import re
import secrets
import shlex
import subprocess
import sys
import tempfile
import time
import uuid
from pathlib import Path
from typing import Any


CONTRACT_ID = "external-mutation-guard-v1"
SCHEMA_VERSION = 1
STATE_REL = Path(".artifact-delivery/external-mutation")
KEY_NAME = ".guard-key"
TTL_SECONDS = 900
CONFIRM_RE = re.compile(r"^CONFIRM EXTERNAL MUTATION ([0-9A-F]{24})$")
INTENT_KIND = "intent"
# 人間の自然文リクエストで自動承認してよい操作クラス。取り消し可能な範囲だけを列挙する。
AUTO_GRANT_CLASSES = frozenset({"github-pr-write", "github-issue-write", "beads-issue-write"})
GH_PR_AUTO_VERBS = frozenset({"create", "edit", "comment", "ready"})
GH_ISSUE_AUTO_VERBS = frozenset({"create", "edit", "comment", "close", "reopen"})
BD_AUTO_VERBS = frozenset({"create", "update", "close", "reopen"})
# 自然文の意図宣言。UserPromptSubmit の実イベントでのみ評価され、付与クラスを限定する。
INTENT_PATTERNS: tuple[tuple[re.Pattern[str], frozenset[str]], ...] = (
    (
        re.compile(
            # \bPR\b は使えない: Python の \w は CJK を含むため "PRを出して" で
            # 単語境界が成立せず落ちる。境界判定を ASCII 英字だけに限定する。
            r"(?:プルリク(?:エスト)?|プル\s*リクエスト|pull\s*request|(?<![A-Za-z])PR(?![A-Za-z]))"
            r"[^\n]{0,40}?"
            r"(?:出し|出す|出せ|作成|作って|作る|上げ|開い|投げ|送っ|create|open|raise|submit)",
            re.I,
        ),
        frozenset({"github-pr-write"}),
    ),
    (
        re.compile(
            r"(?:issue|イシュー|課題|チケット)"
            r"[^\n]{0,40}?"
            r"(?:立て|作成|作って|作る|閉じ|クローズ|更新|create|close|reopen|update)",
            re.I,
        ),
        frozenset({"github-issue-write", "beads-issue-write"}),
    ),
)
ENTRYPOINT_RE = re.compile(r"^plugin:[a-z0-9][a-z0-9-]*/skills/[a-z0-9][a-z0-9-]*/SKILL\.md$")
PYTHON_RE = re.compile(r"^python3(?:\.\d+)?$")
RUNNER_NAME = "build-external-mutation-guard.py"
SHELL_CONTROL_TOKENS = frozenset({";", "&", "&&", "|", "||", "<", ">", "<<", ">>", "(", ")"})
CANONICAL_ACTION_FLAGS = {
    "preview": frozenset(
        {
            "--project-root",
            "--entrypoint-ref",
            "--target-scope",
            "--diff-summary",
            "--side-effect-summary",
            "--command-json",
        }
    ),
    "authorize": frozenset(
        {"--project-root", "--preview-receipt", "--confirmation-receipt"}
    ),
    "authorize-intent": frozenset(
        {"--project-root", "--preview-receipt", "--intent-receipt"}
    ),
    "execute": frozenset(
        {"--project-root", "--authorization-receipt", "--command-json"}
    ),
    "cancel": frozenset({"--project-root", "--preview-receipt"}),
}
DIRECT_MUTATION_PATTERNS = (
    re.compile(r"\bcurl\b[^\n]*(?:-X|--request)\s*(?:POST|PUT|PATCH|DELETE)\b", re.I),
    re.compile(r"\bcurl\b[^\n]*(?:--data(?:-raw|-binary)?|-d)\s", re.I),
    re.compile(r"\bgh\s+(?:issue|pr)\s+(?:create|edit|close|reopen|merge|comment)\b", re.I),
    re.compile(r"\bgh\s+api\b[^\n]*(?:-X|--method)\s*(?:POST|PUT|PATCH|DELETE)\b", re.I),
    re.compile(r"\bbd\s+(?:create|update|close|reopen|delete|dep\s+add)\b", re.I),
    re.compile(r"\b(?:send-campaign|publish-notion-page|notion-submit-improvement)\.py\b", re.I),
    re.compile(r"\bgh-bridge\.py\b[^\n]*\bapply\b", re.I),
    re.compile(r"\bintake_publish_pipeline\.py\b", re.I),
    re.compile(r"\bsetup-send-log-db\.py\b[^\n]*--apply\b", re.I),
)


class GuardError(ValueError):
    """Fail-closed receipt or execution contract violation."""


def _compact(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def _ordered_output(value: dict[str, Any]) -> str:
    """Preserve human-review field order; receipt canonicalization remains sorted."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


def _sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _sha256_file(path: Path) -> str:
    return _sha256_bytes(path.read_bytes())


def _command(value: str) -> list[str]:
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError as exc:
        raise GuardError(f"command-json is invalid JSON: {exc}") from exc
    if (
        not isinstance(parsed, list)
        or not parsed
        or not all(isinstance(item, str) and item for item in parsed)
    ):
        raise GuardError("command-json must be a non-empty JSON string array")
    return parsed


def _command_sha256(argv: list[str]) -> str:
    return _sha256_bytes(_compact(argv).encode("utf-8"))


def _action_class(argv: list[str]) -> str | None:
    """Classify argv into an auto-grantable class; unknown or irreversible argv stays None."""
    program = Path(argv[0]).name
    rest = argv[1:]
    if program == "gh" and len(rest) >= 2:
        surface, verb = rest[0], rest[1]
        if surface == "pr" and verb in GH_PR_AUTO_VERBS:
            return "github-pr-write"
        if surface == "issue" and verb in GH_ISSUE_AUTO_VERBS:
            return "github-issue-write"
        return None
    if program == "bd" and rest:
        if rest[0] in BD_AUTO_VERBS:
            return "beads-issue-write"
        if rest[0] == "dep" and len(rest) >= 2 and rest[1] == "add":
            return "beads-issue-write"
    return None


def _intent_classes(prompt: str) -> frozenset[str]:
    granted: set[str] = set()
    for pattern, classes in INTENT_PATTERNS:
        if pattern.search(prompt):
            granted |= set(classes)
    return frozenset(granted & AUTO_GRANT_CLASSES)


def _review_text(value: str, *, name: str) -> str:
    normalized = " ".join(value.split())
    if not normalized:
        raise GuardError(f"{name} must be non-empty")
    if len(normalized.encode("utf-8")) > 2048:
        raise GuardError(f"{name} exceeds 2048 UTF-8 bytes")
    return normalized


def _project_root(value: str) -> Path:
    try:
        root = Path(value).expanduser().resolve(strict=True)
    except OSError as exc:
        raise GuardError(f"project root does not exist: {value}") from exc
    if not root.is_dir():
        raise GuardError(f"project root is not a directory: {root}")
    return root


def _state_dir(root: Path, *, create: bool) -> Path:
    state = root / STATE_REL
    if create:
        state.mkdir(parents=True, exist_ok=True)
        os.chmod(state, 0o700)
    try:
        resolved = state.resolve(strict=True)
    except OSError as exc:
        raise GuardError(f"guard state is unavailable: {state}") from exc
    try:
        resolved.relative_to(root)
    except ValueError as exc:
        raise GuardError("guard state escapes project root") from exc
    return resolved


def _key(state: Path, *, create: bool) -> bytes:
    path = state / KEY_NAME
    if create and not path.exists():
        try:
            descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        except FileExistsError:
            pass
        else:
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(secrets.token_bytes(32))
    try:
        value = path.read_bytes()
    except OSError as exc:
        raise GuardError("guard key is unavailable") from exc
    if len(value) != 32:
        raise GuardError("guard key is invalid")
    return value


def _seal(body: dict[str, Any], key: bytes) -> str:
    unsigned = {name: value for name, value in body.items() if name != "seal"}
    return hmac.new(key, _compact(unsigned).encode("utf-8"), hashlib.sha256).hexdigest()


def _write_receipt(state: Path, name: str, body: dict[str, Any], key: bytes) -> Path:
    destination = state / name
    if destination.exists():
        raise GuardError(f"receipt already exists: {destination.name}")
    document = {**body, "seal": _seal(body, key)}
    descriptor, temporary = tempfile.mkstemp(prefix=f".{name}.", dir=state)
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(document, handle, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, 0o600)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return destination


def _write_once(state: Path, name: str, body: dict[str, Any], key: bytes) -> Path:
    """Atomically create a sealed claim; an existing claim is never replaced."""
    destination = state / name
    document = {**body, "seal": _seal(body, key)}
    try:
        descriptor = os.open(destination, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError as exc:
        raise GuardError("preview and confirmation were already consumed by authorization") from exc
    try:
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            json.dump(document, handle, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
    except BaseException:
        # A partially written O_EXCL claim remains fail-closed and cannot be replayed.
        raise
    return destination


def _receipt(state: Path, raw_path: str, expected_kind: str, key: bytes) -> tuple[Path, dict[str, Any]]:
    try:
        path = Path(raw_path).expanduser().resolve(strict=True)
        path.relative_to(state)
    except (OSError, ValueError) as exc:
        raise GuardError("receipt path is outside canonical guard state") from exc
    try:
        document = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise GuardError(f"receipt is unreadable: {path}") from exc
    if not isinstance(document, dict):
        raise GuardError("receipt root must be an object")
    if document.get("contract_id") != CONTRACT_ID or document.get("schema_version") != SCHEMA_VERSION:
        raise GuardError("receipt contract identity drift")
    if document.get("kind") != expected_kind:
        raise GuardError(f"expected {expected_kind} receipt")
    seal = document.get("seal")
    if not isinstance(seal, str) or not hmac.compare_digest(seal, _seal(document, key)):
        raise GuardError("receipt seal mismatch; receipt may be tampered")
    expires_at = document.get("expires_at")
    if not isinstance(expires_at, int) or expires_at < int(time.time()):
        raise GuardError("receipt expired")
    return path, document


def _base(kind: str, receipt_id: str, *, now: int) -> dict[str, Any]:
    return {
        "schema_version": SCHEMA_VERSION,
        "contract_id": CONTRACT_ID,
        "kind": kind,
        "receipt_id": receipt_id,
        "issued_at": now,
        # Second resolution cannot order two receipts issued inside the same second.
        "issued_at_ns": time.time_ns(),
        "expires_at": now + TTL_SECONDS,
    }


def _issued_ns(receipt: dict[str, Any]) -> int:
    value = receipt.get("issued_at_ns")
    if isinstance(value, int):
        return value
    return int(receipt["issued_at"]) * 1_000_000_000


def preview(args: argparse.Namespace) -> dict[str, Any]:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=True)
    key = _key(state, create=True)
    argv = _command(args.command_json)
    if not ENTRYPOINT_RE.fullmatch(args.entrypoint_ref):
        raise GuardError("entrypoint-ref must be a canonical plugin SKILL.md ref")
    target_scope = _review_text(args.target_scope, name="target-scope")
    diff_summary = _review_text(args.diff_summary, name="diff-summary")
    side_effect_summary = _review_text(args.side_effect_summary, name="side-effect-summary")
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    challenge = secrets.token_hex(12).upper()
    action_class = _action_class(argv)
    body = {
        **_base("preview", receipt_id, now=now),
        "entrypoint_ref": args.entrypoint_ref,
        "target_scope": target_scope,
        "command_argv": argv,
        "command_sha256": _command_sha256(argv),
        "action_class": action_class,
        "diff_summary": diff_summary,
        "side_effect_summary": side_effect_summary,
        "challenge_sha256": _sha256_bytes(challenge.encode("ascii")),
        "status": "pending-user-confirmation",
    }
    path = _write_receipt(state, f"preview-{receipt_id}.json", body, key)
    auto_grantable = action_class in AUTO_GRANT_CLASSES
    instruction = f"Reply exactly: CONFIRM EXTERNAL MUTATION {challenge}"
    if auto_grantable:
        instruction = (
            f"A live intent grant covering {action_class} authorizes this via authorize-intent; "
            f"otherwise reply exactly: CONFIRM EXTERNAL MUTATION {challenge}"
        )
    return {
        "contract_id": CONTRACT_ID,
        "status": "preview-created",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "target_scope": target_scope,
        "command_argv": argv,
        "action_class": action_class,
        "auto_grantable": auto_grantable,
        "diff_summary": diff_summary,
        "side_effect_summary": side_effect_summary,
        "challenge": challenge,
        "user_instruction": instruction,
    }


def _read_hook_payload() -> dict[str, Any]:
    try:
        value = json.loads(sys.stdin.read() or "{}")
    except json.JSONDecodeError:
        return {}
    return value if isinstance(value, dict) else {}


def hook_confirm() -> dict[str, Any] | None:
    payload = _read_hook_payload()
    if payload.get("hook_event_name") not in {None, "UserPromptSubmit"}:
        return None
    prompt = payload.get("prompt")
    cwd = payload.get("cwd")
    session_id = payload.get("session_id")
    if not isinstance(prompt, str) or not isinstance(cwd, str) or not isinstance(session_id, str):
        return None
    stripped = prompt.strip()
    root = _project_root(cwd)
    matched = CONFIRM_RE.fullmatch(stripped)
    if matched is not None:
        return _confirm_challenge(root, stripped, session_id, matched.group(1))
    granted = _intent_classes(stripped)
    if not granted:
        return None
    return _grant_intent(root, stripped, session_id, granted)


def _user_event_id(session_id: str, prompt: str) -> str:
    return _sha256_bytes(f"{session_id}\0{prompt}".encode("utf-8"))


def _confirm_challenge(
    root: Path, prompt: str, session_id: str, challenge: str
) -> dict[str, Any]:
    """Bind a typed challenge to its single live preview.

    A challenge that matches no live preview creates no receipt and does not block the
    prompt: refusing the user's message buys no safety and strands the session.
    """
    unmatched = {
        "contract_id": CONTRACT_ID,
        "status": "confirmation-unmatched",
        "detail": "no live preview matches this challenge; it may have expired or been consumed",
    }
    try:
        state = _state_dir(root, create=False)
        key = _key(state, create=False)
    except GuardError:
        return unmatched
    challenge_hash = _sha256_bytes(challenge.encode("ascii"))
    candidates: list[tuple[Path, dict[str, Any]]] = []
    for path in sorted(state.glob("preview-*.json")):
        try:
            loaded_path, receipt = _receipt(state, str(path), "preview", key)
        except GuardError:
            continue
        if receipt.get("challenge_sha256") == challenge_hash:
            candidates.append((loaded_path, receipt))
    if len(candidates) != 1:
        return unmatched
    preview_path, preview_receipt = candidates[0]
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    body = {
        **_base("confirmation", receipt_id, now=now),
        "preview_receipt_id": preview_receipt["receipt_id"],
        "preview_receipt_sha256": _sha256_file(preview_path),
        "producer": "claude-code-user-prompt-submit",
        "user_event_id": _user_event_id(session_id, prompt),
        "decision": "confirm",
    }
    path = _write_receipt(state, f"confirmation-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "confirmation-created",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
    }


def _grant_intent(
    root: Path, prompt: str, session_id: str, granted: frozenset[str]
) -> dict[str, Any]:
    """Seal a single-use grant proving a human asked for this class of mutation."""
    state = _state_dir(root, create=True)
    key = _key(state, create=True)
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    body = {
        **_base(INTENT_KIND, receipt_id, now=now),
        "granted_classes": sorted(granted),
        "producer": "claude-code-user-prompt-submit",
        "user_event_id": _user_event_id(session_id, prompt),
        "prompt_excerpt": " ".join(prompt.split())[:200],
        "decision": "confirm-by-intent",
    }
    path = _write_receipt(state, f"{INTENT_KIND}-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "intent-granted",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "granted_classes": sorted(granted),
    }


def authorize(args: argparse.Namespace) -> dict[str, Any]:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    confirmation_path, confirmation_receipt = _receipt(
        state, args.confirmation_receipt, "confirmation", key
    )
    if (
        confirmation_receipt.get("preview_receipt_id") != preview_receipt["receipt_id"]
        or confirmation_receipt.get("preview_receipt_sha256") != _sha256_file(preview_path)
    ):
        raise GuardError("confirmation receipt is not bound to the supplied preview receipt")
    return _seal_authorization(
        state,
        key,
        preview_path,
        preview_receipt,
        confirmation_path,
        confirmation_receipt,
        confirmation_kind="confirmation",
    )


def authorize_intent(args: argparse.Namespace) -> dict[str, Any]:
    """Authorize an auto-grantable preview against a live human intent grant."""
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    intent_path, intent_receipt = _receipt(state, args.intent_receipt, INTENT_KIND, key)
    action_class = preview_receipt.get("action_class")
    if action_class not in AUTO_GRANT_CLASSES:
        raise GuardError(
            "preview action class is not auto-grantable; use the typed confirmation flow"
        )
    granted = intent_receipt.get("granted_classes")
    if not isinstance(granted, list) or action_class not in granted:
        raise GuardError("intent grant does not cover the preview action class")
    if _issued_ns(intent_receipt) > _issued_ns(preview_receipt):
        raise GuardError("preview predates the intent grant; the user request must come first")
    _write_once(
        state,
        f"intent-claim-{intent_receipt['receipt_id']}.json",
        {
            "contract_id": CONTRACT_ID,
            "schema_version": SCHEMA_VERSION,
            "kind": "intent-claim",
            "intent_receipt_id": intent_receipt["receipt_id"],
            "intent_receipt_sha256": _sha256_file(intent_path),
            "preview_receipt_id": preview_receipt["receipt_id"],
            "claimed_at": int(time.time()),
        },
        key,
    )
    return _seal_authorization(
        state,
        key,
        preview_path,
        preview_receipt,
        intent_path,
        intent_receipt,
        confirmation_kind=INTENT_KIND,
    )


def _seal_authorization(
    state: Path,
    key: bytes,
    preview_path: Path,
    preview_receipt: dict[str, Any],
    confirmation_path: Path,
    confirmation_receipt: dict[str, Any],
    *,
    confirmation_kind: str,
) -> dict[str, Any]:
    now = int(time.time())
    preview_sha256 = _sha256_file(preview_path)
    confirmation_sha256 = _sha256_file(confirmation_path)
    _write_once(
        state,
        f"authorization-claim-preview-{preview_receipt['receipt_id']}.json",
        {
            "contract_id": CONTRACT_ID,
            "schema_version": SCHEMA_VERSION,
            "kind": "authorization-claim",
            "preview_receipt_id": preview_receipt["receipt_id"],
            "preview_receipt_sha256": preview_sha256,
            "confirmation_receipt_id": confirmation_receipt["receipt_id"],
            "confirmation_receipt_sha256": confirmation_sha256,
            "claimed_at": now,
        },
        key,
    )
    receipt_id = uuid.uuid4().hex
    body = {
        **_base("authorization", receipt_id, now=now),
        "preview_receipt_id": preview_receipt["receipt_id"],
        "preview_receipt_sha256": preview_sha256,
        "confirmation_receipt_id": confirmation_receipt["receipt_id"],
        "confirmation_receipt_sha256": confirmation_sha256,
        "confirmation_receipt_kind": confirmation_kind,
        "entrypoint_ref": preview_receipt["entrypoint_ref"],
        "target_scope": preview_receipt["target_scope"],
        "command_sha256": preview_receipt["command_sha256"],
        "status": "authorized-once",
    }
    path = _write_receipt(state, f"authorization-{receipt_id}.json", body, key)
    return {
        "contract_id": CONTRACT_ID,
        "status": "authorized",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
        "confirmation_receipt_kind": confirmation_kind,
    }


def cancel(args: argparse.Namespace) -> dict[str, Any]:
    """Resolve a preview without executing it so pending guard context stops blocking Bash."""
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    preview_path, preview_receipt = _receipt(state, args.preview_receipt, "preview", key)
    now = int(time.time())
    receipt_id = uuid.uuid4().hex
    path = _write_receipt(
        state,
        f"cancellation-preview-{preview_receipt['receipt_id']}.json",
        {
            **_base("cancellation", receipt_id, now=now),
            "preview_receipt_id": preview_receipt["receipt_id"],
            "preview_receipt_sha256": _sha256_file(preview_path),
            "status": "cancelled",
        },
        key,
    )
    return {
        "contract_id": CONTRACT_ID,
        "status": "cancelled",
        "receipt_path": str(path),
        "receipt_sha256": _sha256_file(path),
    }


def execute(args: argparse.Namespace) -> int:
    root = _project_root(args.project_root)
    state = _state_dir(root, create=False)
    key = _key(state, create=False)
    authorization_path, authorization = _receipt(
        state, args.authorization_receipt, "authorization", key
    )
    argv = _command(args.command_json)
    if authorization.get("command_sha256") != _command_sha256(argv):
        raise GuardError("execute command digest differs from authorized preview")
    preview_path = state / f"preview-{authorization['preview_receipt_id']}.json"
    confirmation_kind = authorization.get("confirmation_receipt_kind", "confirmation")
    if confirmation_kind not in {"confirmation", INTENT_KIND}:
        raise GuardError("authorization names an unknown confirmation receipt kind")
    confirmation_path = (
        state / f"{confirmation_kind}-{authorization['confirmation_receipt_id']}.json"
    )
    if _sha256_file(preview_path) != authorization.get("preview_receipt_sha256"):
        raise GuardError("preview receipt changed after authorization")
    if _sha256_file(confirmation_path) != authorization.get("confirmation_receipt_sha256"):
        raise GuardError("confirmation receipt changed after authorization")
    consumed = state / f"consumed-{authorization['receipt_id']}.json"
    try:
        descriptor = os.open(consumed, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError as exc:
        raise GuardError("authorization receipt was already consumed") from exc
    with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
        json.dump(
            {
                "authorization_receipt_sha256": _sha256_file(authorization_path),
                "consumed_at": int(time.time()),
            },
            handle,
            sort_keys=True,
        )
        handle.write("\n")
    completed = subprocess.run(argv, cwd=root, text=True, capture_output=True, shell=False, check=False)
    if completed.stdout:
        sys.stdout.write(completed.stdout)
    if completed.stderr:
        sys.stderr.write(completed.stderr)
    if completed.returncode == 0:
        now = int(time.time())
        completion_id = uuid.uuid4().hex
        _write_receipt(
            state,
            f"completion-preview-{authorization['preview_receipt_id']}.json",
            {
                **_base("completion", completion_id, now=now),
                "preview_receipt_id": authorization["preview_receipt_id"],
                "authorization_receipt_id": authorization["receipt_id"],
                "authorization_receipt_sha256": _sha256_file(authorization_path),
                "status": "executed-successfully",
            },
            key,
        )
    return completed.returncode


def _canonical_guard_action(command: str) -> str | None:
    """Return the action only when the entire shell command is one canonical guard call."""
    try:
        lexer = shlex.shlex(command, posix=True, punctuation_chars=";&|<>()")
        lexer.whitespace_split = True
        lexer.commenters = ""
        tokens = list(lexer)
    except ValueError:
        return None
    if len(tokens) < 3 or any(token in SHELL_CONTROL_TOKENS for token in tokens):
        return None
    if not PYTHON_RE.fullmatch(Path(tokens[0]).name) or Path(tokens[1]).name != RUNNER_NAME:
        return None
    action = tokens[2]
    expected_flags = CANONICAL_ACTION_FLAGS.get(action)
    rest = tokens[3:]
    if expected_flags is None or len(rest) != 2 * len(expected_flags):
        return None
    supplied: dict[str, str] = {}
    for index in range(0, len(rest), 2):
        flag, value = rest[index : index + 2]
        if flag not in expected_flags or flag in supplied or not value:
            return None
        supplied[flag] = value
    return action if set(supplied) == expected_flags else None


def _has_pending_guard_context(payload: dict[str, Any]) -> bool:
    cwd = payload.get("cwd")
    if not isinstance(cwd, str) or not cwd:
        return False
    try:
        root = _project_root(cwd)
    except GuardError:
        return False
    if not (root / STATE_REL).exists():
        return False
    try:
        state = _state_dir(root, create=False)
        key = _key(state, create=False)
    except GuardError:
        # Existing but unreadable/non-canonical guard state cannot prove safety.
        return True
    for preview_path in sorted(state.glob("preview-*.json")):
        try:
            _, preview_receipt = _receipt(state, str(preview_path), "preview", key)
        except GuardError as exc:
            if "expired" in str(exc):
                continue
            # A malformed receipt inside canonical state cannot safely prove no pending mutation.
            return True
        resolution: tuple[str, Path, str] | None = None
        for kind, terminal_status in (
            ("completion", "executed-successfully"),
            ("cancellation", "cancelled"),
        ):
            candidate = state / f"{kind}-preview-{preview_receipt['receipt_id']}.json"
            if candidate.is_file():
                resolution = (kind, candidate, terminal_status)
                break
        if resolution is None:
            return True
        kind, resolution_path, terminal_status = resolution
        try:
            _, resolved = _receipt(state, str(resolution_path), kind, key)
        except GuardError:
            return True
        if (
            resolved.get("preview_receipt_id") != preview_receipt["receipt_id"]
            or resolved.get("status") != terminal_status
        ):
            return True
    return False


def _deny(reason: str) -> dict[str, Any]:
    return {
        "hookSpecificOutput": {
            "hookEventName": "PreToolUse",
            "permissionDecision": "deny",
            "permissionDecisionReason": reason,
        }
    }


def pretool() -> dict[str, Any] | None:
    payload = _read_hook_payload()
    if payload.get("hook_event_name") not in {None, "PreToolUse"}:
        return None
    if payload.get("tool_name") != "Bash":
        return None
    tool_input = payload.get("tool_input")
    command = tool_input.get("command") if isinstance(tool_input, dict) else None
    if not isinstance(command, str) or not command.strip():
        return None
    if _canonical_guard_action(command) is not None:
        return None
    if RUNNER_NAME in command:
        return _deny(
            "Malformed central guard invocation is blocked: the full Bash command must be "
            "exactly one canonical preview, authorize, or execute call with no shell operators."
        )
    if _has_pending_guard_context(payload):
        return _deny(
            "A pending guard context blocks non-canonical Bash execution until its exact "
            "preview -> confirmation -> authorize -> execute flow completes or expires."
        )
    if not any(pattern.search(command) for pattern in DIRECT_MUTATION_PATTERNS):
        return None
    return _deny(
        "Direct external mutation is blocked. Use build-external-mutation-guard.py "
        "preview -> user confirmation -> authorize -> execute."
    )


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="action", required=True)
    preview_parser = commands.add_parser("preview")
    preview_parser.add_argument("--project-root", required=True)
    preview_parser.add_argument("--entrypoint-ref", required=True)
    preview_parser.add_argument("--target-scope", required=True)
    preview_parser.add_argument("--diff-summary", required=True)
    preview_parser.add_argument("--side-effect-summary", required=True)
    preview_parser.add_argument("--command-json", required=True)
    commands.add_parser("hook-confirm")
    authorize_parser = commands.add_parser("authorize")
    authorize_parser.add_argument("--project-root", required=True)
    authorize_parser.add_argument("--preview-receipt", required=True)
    authorize_parser.add_argument("--confirmation-receipt", required=True)
    authorize_intent_parser = commands.add_parser("authorize-intent")
    authorize_intent_parser.add_argument("--project-root", required=True)
    authorize_intent_parser.add_argument("--preview-receipt", required=True)
    authorize_intent_parser.add_argument("--intent-receipt", required=True)
    cancel_parser = commands.add_parser("cancel")
    cancel_parser.add_argument("--project-root", required=True)
    cancel_parser.add_argument("--preview-receipt", required=True)
    execute_parser = commands.add_parser("execute")
    execute_parser.add_argument("--project-root", required=True)
    execute_parser.add_argument("--authorization-receipt", required=True)
    execute_parser.add_argument("--command-json", required=True)
    commands.add_parser("pretool")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        if args.action == "preview":
            print(_ordered_output(preview(args)))
            return 0
        if args.action == "hook-confirm":
            result = hook_confirm()
            if result is not None:
                print(
                    _compact(
                        {
                            "continue": True,
                            "suppressOutput": True,
                            "hookSpecificOutput": {
                                "hookEventName": "UserPromptSubmit",
                                "additionalContext": "[external-mutation-confirmation]\n"
                                + _compact(result),
                            },
                        }
                    )
                )
            return 0
        if args.action == "authorize":
            print(_compact(authorize(args)))
            return 0
        if args.action == "authorize-intent":
            print(_compact(authorize_intent(args)))
            return 0
        if args.action == "cancel":
            print(_compact(cancel(args)))
            return 0
        if args.action == "execute":
            return execute(args)
        result = pretool()
        if result is not None:
            print(_compact(result))
        return 0
    except (GuardError, OSError, KeyError, subprocess.SubprocessError) as exc:
        print(f"EXTERNAL_MUTATION_GUARD_ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
# /// script
# name: schedule-graph
# purpose: Compute deterministic feature/task ready sets and non-conflicting worktree batches.
# inputs: ["argv: --graph FILE --ready-source self|bd-bridge --ready-json FILE? --leases FILE?"]
# outputs: ["stdout: JSON schedule"]
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
from __future__ import annotations

import argparse
import sys
from pathlib import Path
from typing import Any

from _common import ContractError, dump, load_json


def touches(node: dict[str, Any]) -> set[str]:
    """Return the canonical graph-node `resource_scope: string[]` value.

    Older prototypes used ``{"touches": [...]}``, but that shape contradicts
    graph-node.schema.json and silently erased every scope during scheduling.
    Reject the stale shape instead of producing an unsafe parallel batch.
    """
    values = node.get("resource_scope", [])
    if not isinstance(values, list) or any(
        not isinstance(value, str) or not value for value in values
    ):
        node_id = node.get("graph_node_id") or node.get("id") or "<unknown>"
        raise ContractError(f"{node_id}: resource_scope must be a non-empty string[]")
    return set(values)


def is_schedulable(node: dict[str, Any]) -> bool:
    readiness = node.get("implementation_readiness") or {}
    return (
        node.get("status") == "active"
        and node.get("confirmation_status") == "confirmed"
        and node.get("evaluation_status") == "pass"
        and isinstance(readiness, dict)
        and readiness.get("status") == "complete"
    )


def main() -> int:
    parser = argparse.ArgumentParser(); parser.add_argument("--graph", required=True)
    parser.add_argument("--ready-source", choices=("self", "bd-bridge"), default="self")
    parser.add_argument("--ready-json"); parser.add_argument("--leases")
    args = parser.parse_args(); data = load_json(Path(args.graph)); nodes = data.get("nodes", []) if isinstance(data, dict) else data
    if not isinstance(nodes, list): raise ContractError("graph nodes must be an array")
    by_id = {(n.get("graph_node_id") or n.get("id")): n for n in nodes if isinstance(n, dict)}
    done = {node_id for node_id, node in by_id.items() if node.get("status") in {"done", "closed"}}
    ready_ids: set[str]
    unmapped: list[dict[str, Any]] = []
    if args.ready_source == "bd-bridge":
        if not args.ready_json: raise ContractError("--ready-source bd-bridge requires --ready-json")
        ready_data = load_json(Path(args.ready_json)); raw_ready = ready_data.get("ready_set", ready_data)
        if not isinstance(raw_ready, list): raise ContractError("bd ready payload must contain ready_set[]")
        ready_ids = set()
        for item in raw_ready:
            external = item.get("external_ref") if isinstance(item, dict) else None
            if external and external in by_id:
                if is_schedulable(by_id[external]) and all(
                    dep in done for dep in by_id[external].get("depends_on", [])
                ):
                    ready_ids.add(external)
            else: unmapped.append(item if isinstance(item, dict) else {"value": item})
    else:
        ready_ids = {node_id for node_id, node in by_id.items() if is_schedulable(node)
                     and all(dep in done for dep in node.get("depends_on", []))}
    active_leases: list[dict[str, Any]] = []
    if args.leases and Path(args.leases).exists():
        lease_data = load_json(Path(args.leases)); active_leases = lease_data.get("leases", lease_data if isinstance(lease_data, list) else [])
    leased_ids = {x.get("graph_node_id") for x in active_leases if x.get("state") not in {"released", "expired"}}
    leased_touches = {str(v) for x in active_leases if x.get("state") not in {"released", "expired"} for v in x.get("resource_scope", [])}
    candidates = [by_id[x] for x in sorted(ready_ids) if x in by_id and is_schedulable(by_id[x])
                  and x not in leased_ids and not (touches(by_id[x]) & leased_touches)]
    features = [n for n in candidates if n.get("artifact_kind", n.get("kind")) == "feature"]
    tasks = [n for n in candidates if n not in features]
    def batches(items: list[dict[str, Any]]) -> list[list[str]]:
        result: list[list[str]] = []
        for node in items:
            node_id = node.get("graph_node_id") or node.get("id"); scope = touches(node)
            placed = False
            for batch in result:
                occupied = set().union(*(touches(by_id[x]) for x in batch))
                if not scope & occupied: batch.append(node_id); placed = True; break
            if not placed: result.append([node_id])
        return result
    feature_batches, task_batches = batches(features), batches(tasks)
    conflicts = sorted((ready_ids & leased_ids) | {x for x in ready_ids if x in by_id and touches(by_id[x]) & leased_touches})
    hints = []
    for node in tasks:
        node_id = node.get("graph_node_id") or node.get("id")
        branch = f"devgraph/{node_id}"
        hints.append({"graph_node_id": node_id, "suggested_branch": branch,
                      "claim_command": f"/dev-graph worktree claim {node_id} --branch {branch} --session-id <session>"})
    dump({"ready_set": {"features": [n.get("graph_node_id") or n.get("id") for n in features],
                         "tasks": [n.get("graph_node_id") or n.get("id") for n in tasks]},
          "batches": {"features": feature_batches, "tasks": task_batches}, "conflicts": conflicts,
          "assignment_hints": hints, "unmapped": unmapped, "ready_source": args.ready_source})
    return 0


if __name__ == "__main__":
    try: raise SystemExit(main())
    except ContractError as exc: print(str(exc), file=sys.stderr); raise SystemExit(2)

#!/usr/bin/env python3
# /// script
# name: resolve-repo-context
# purpose: Resolve and verify worktree content authority and shared Git coordination authority.
# inputs: ["argv: --repo-root PATH? --config PATH --mode read|write"]
# outputs: ["stdout: JSON repository/worktree context"]
# requires-python = ">=3.10"
# dependencies: []
# contexts: [A, B, C, E]
# network: false
# write-scope: none
# ///
from __future__ import annotations

import argparse
import hashlib
import os
import re
import sys
from pathlib import Path
from typing import Any

from _common import ContractError, contained, dump, git, load_json, stable_id


DEFAULT_CONTENT_ROOTS = {
    "issues": "issues",
    "tasks": "tasks",
    "specifications": "specs",
    "architecture": "architecture",
    "features": "features",
    "documents": "docs",
    "system_spec": "system-spec",
}
DEFAULT_LOCAL_STATE = {
    "graph": ".dev-graph/state/graph.json",
    "cache": ".dev-graph/cache",
    "locks": ".dev-graph/locks",
}
GITHUB_REMOTE = re.compile(
    r"^(?:https?://github\.com/|ssh://git@github\.com/|git@github\.com:)([^/]+)/(.+?)(?:\.git)?/?$",
    re.IGNORECASE,
)


def discover(explicit: str | None) -> tuple[Path, str]:
    choices: list[tuple[str, str]] = []
    if explicit:
        choices.append((explicit, "explicit --repo-root"))
    trusted = os.environ.get("CLAUDE_PROJECT_DIR")
    if trusted:
        choices.append((trusted, "CLAUDE_PROJECT_DIR"))
    cp = __import__("subprocess").run(
        ["git", "rev-parse", "--show-toplevel"], text=True, capture_output=True, check=False
    )
    if cp.returncode == 0:
        choices.append((cp.stdout.strip(), "git toplevel"))
    for parent in (Path.cwd(), *Path.cwd().parents):
        if (parent / ".git").exists() or (parent / ".dev-graph").is_dir():
            choices.append((str(parent), "cwd marker"))
            break
    if not choices:
        raise ContractError("repository root cannot be resolved")
    root = Path(choices[0][0]).expanduser().resolve(strict=True)
    actual = Path(git(["rev-parse", "--show-toplevel"], root)).resolve(strict=True)
    if root != actual:
        raise ContractError(f"selected root is not current worktree root: {root} != {actual}")
    if trusted and Path(trusted).expanduser().resolve(strict=True) != root:
        raise ContractError("--repo-root and CLAUDE_PROJECT_DIR disagree")
    return root, choices[0][1]


def repository_id_for(remote: str, common: Path) -> str:
    """Derive the durable repository identity from the canonical authority."""
    match = GITHUB_REMOTE.fullmatch(remote.strip()) if remote else None
    if match:
        owner, repository = match.groups()
        return f"github:{owner}/{repository.removesuffix('.git')}"
    digest = hashlib.sha256(str(common.resolve(strict=True)).encode("utf-8")).hexdigest()
    return f"local:sha256:{digest}"


def _absolute_git_path(raw: str, root: Path) -> Path:
    path = Path(raw)
    return (root / path).resolve(strict=True) if not path.is_absolute() else path.resolve(strict=True)


def verify_common_ownership(root: Path, git_dir: Path, common: Path) -> None:
    """Prove that the selected worktree and common directory are one repository."""
    try:
        objects = _absolute_git_path(git(["rev-parse", "--git-path", "objects"], root), root)
        config = _absolute_git_path(git(["rev-parse", "--git-path", "config"], root), root)
        common_objects = (common / "objects").resolve(strict=True)
        common_config = (common / "config").resolve(strict=True)
    except OSError as exc:
        raise ContractError(f"git common dir authority is incomplete: {common}: {exc}") from exc
    if objects != common_objects:
        raise ContractError("git common dir objects authority does not belong to selected repository")
    if config != common_config:
        raise ContractError("git common dir config authority does not belong to selected repository")
    if git_dir != common:
        marker = git_dir / "commondir"
        if not marker.is_file() or marker.is_symlink():
            raise ContractError(f"worktree git dir has no trusted commondir marker: {marker}")
        try:
            declared = (git_dir / marker.read_text(encoding="utf-8").strip()).resolve(strict=True)
        except OSError as exc:
            raise ContractError(f"invalid worktree commondir marker: {marker}: {exc}") from exc
        if declared != common:
            raise ContractError(f"worktree commondir mismatch: {declared} != {common}")
    root_remote = git(["remote", "get-url", "origin"], root, check=False)
    common_remote = git(["--git-dir", str(common), "remote", "get-url", "origin"], root, check=False)
    if root_remote != common_remote:
        raise ContractError("worktree and git common dir resolve different origin remotes")


def _validate_relative(raw: Any, label: str) -> Path:
    if not isinstance(raw, str) or not raw or "\x00" in raw:
        raise ContractError(f"{label} must be a non-empty repository-relative path")
    relative = Path(raw)
    if relative.is_absolute() or ".." in relative.parts:
        raise ContractError(f"{label} escapes repository authority: {raw}")
    return relative


def resolve_declared_path(root: Path, raw: Any, label: str, *, reject_leaf_symlink: bool) -> Path:
    """Resolve an existing target or its longest existing parent without escaping root."""
    relative = _validate_relative(raw, label)
    candidate = root / relative
    current = root
    for part in relative.parts:
        current = current / part
        if current.is_symlink():
            try:
                target = current.resolve(strict=True)
            except OSError as exc:
                raise ContractError(f"broken content symlink for {label}: {current}: {exc}") from exc
            contained(target, root)
            if reject_leaf_symlink:
                raise ContractError(f"content root path must not traverse a symlink: {label}={current}")
        if not current.exists() and not current.is_symlink():
            break
    try:
        resolved = candidate.resolve(strict=True) if candidate.exists() or candidate.is_symlink() else candidate.resolve(strict=False)
    except OSError as exc:
        raise ContractError(f"cannot resolve {label}: {candidate}: {exc}") from exc
    contained(resolved, root, must_exist=False)
    return resolved


def resolve_config_paths(root: Path, config: dict[str, Any] | None) -> tuple[dict[str, str], dict[str, str]]:
    config = config or {}
    policy = config.get("path_policy") or {}
    if not isinstance(policy, dict):
        raise ContractError("path_policy must be an object")
    forbidden = (
        policy.get("authority") not in {None, "caller-repository"}
        or policy.get("allow_outside_repository") not in {None, False}
        or policy.get("follow_content_symlinks_outside_repository") not in {None, False}
    )
    if forbidden:
        raise ContractError("path_policy weakens caller-repository containment")
    content = config.get("content_roots") or DEFAULT_CONTENT_ROOTS
    local = config.get("local_state") or DEFAULT_LOCAL_STATE
    if not isinstance(content, dict) or not isinstance(local, dict):
        raise ContractError("content_roots and local_state must be objects")
    resolved_content = {
        key: str(resolve_declared_path(root, value, f"content_roots.{key}", reject_leaf_symlink=True))
        for key, value in sorted(content.items())
    }
    resolved_local = {
        key: str(resolve_declared_path(root, value, f"local_state.{key}", reject_leaf_symlink=False))
        for key, value in sorted(local.items())
    }
    return resolved_content, resolved_local


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo-root")
    parser.add_argument("--config", default=".dev-graph/config.json")
    parser.add_argument("--mode", choices=("read", "write"), default="read")
    args = parser.parse_args()
    root, trust = discover(args.repo_root)
    common_raw = git(["rev-parse", "--git-common-dir"], root)
    common = Path(common_raw)
    if not common.is_absolute():
        common = root / common
    common = common.resolve(strict=True)
    git_dir_raw = git(["rev-parse", "--git-dir"], root)
    git_dir = Path(git_dir_raw)
    if not git_dir.is_absolute():
        git_dir = root / git_dir
    git_dir = git_dir.resolve(strict=True)
    verify_common_ownership(root, git_dir, common)
    remote = git(["remote", "get-url", "origin"], root, check=False)
    repository_id = repository_id_for(remote, common)
    config_arg = Path(args.config)
    if config_arg.is_absolute():
        config_path = contained(config_arg, root, must_exist=False)
    else:
        config_path = root / _validate_relative(args.config, "config")
    config = None
    diagnostics: list[str] = []
    if config_path.exists() or config_path.is_symlink():
        try:
            config_path = contained(config_path, root)
        except OSError as exc:
            raise ContractError(f"broken repository config symlink: {config_path}: {exc}") from exc
        config = load_json(config_path)
        if not isinstance(config, dict):
            raise ContractError("repo config must be a JSON object")
        configured = config.get("repository_id") if isinstance(config, dict) else None
        if configured and configured != repository_id:
            raise ContractError("repo config repository_id does not match derived repository")
    else:
        diagnostics.append("config_missing")
    content_roots, local_state_paths = resolve_config_paths(root, config)
    branch = git(["symbolic-ref", "--quiet", "--short", "HEAD"], root, check=False) or None
    head = git(["rev-parse", "HEAD"], root)
    default_ref = git(["symbolic-ref", "--quiet", "refs/remotes/origin/HEAD"], root, check=False)
    default_branch = default_ref.rsplit("/", 1)[-1] if default_ref else (
        ((config or {}).get("worktrees") or {}).get("default_branch") if isinstance(config, dict) else None
    )
    if not default_branch:
        default_branch = "main"
        diagnostics.append("default_branch_fallback_main")
    worktree_id = stable_id("wt_", repository_id, str(root))
    coord = common / "dev-graph"
    plugin_source = Path(__file__).resolve().parents[1]
    trusted = os.environ.get("CLAUDE_PROJECT_DIR")
    result = {
        "repo_root": str(root), "repository_id": repository_id, "worktree_id": worktree_id,
        "git_common_dir": str(common), "git_dir": str(git_dir), "branch": branch,
        "head_sha": head, "default_branch": default_branch,
        "root_trust_evidence": {"selected_by": trust, "git_toplevel_verified": True,
                                "claude_project_dir_verified": not trusted or Path(trusted).resolve() == root,
                                "git_common_dir_ownership_verified": True},
        "content_roots": {"repository": str(root), **content_roots},
        "local_state_paths": {"config": str(config_path), **local_state_paths},
        "coordination_paths": {"root": str(coord), "leases": str(coord / "leases.json"),
                               "events": str(coord / "events.json")},
        "plugin_source": str(plugin_source), "mode": args.mode, "diagnostics": diagnostics,
    }
    dump(result)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ContractError, OSError) as exc:
        print(str(exc), file=sys.stderr)
        raise SystemExit(1)

