from pathlib import Path
FX = Path("/private/tmp/claude-501/-Users-dm-dev-dev------HarnessHub/512b21d9-0b24-4985-b1b8-d75bd17d8ecf/scratchpad/wt-guard/eval-log/dev-graph/live-trial-fixtures/gm-schedule")
SCR = Path("/private/tmp/claude-501/-private-tmp-claude-501--Users-dm-dev-dev------HarnessHub-512b21d9-0b24-4985-b1b8-d75bd17d8ecf-scratchpad-wt-guard/7096f896-7475-4188-a20b-7627e2f3edb2/scratchpad")
MAX_PARALLEL = 4
nodes = json.loads((FX/".dev-graph/state/graph.json").read_text(encoding="utf-8"))["nodes"]
by_id = {n["graph_node_id"]: n for n in nodes}
rec = json.loads((SCR/"schedule-receipt.json").read_text(encoding="utf-8"))
done = {i for i, n in by_id.items() if n["status"] in {"done", "closed"}}
ready = rec["ready_set"]["tasks"]; feat = rec["ready_set"]["features"]
fail = []

# A1: only fully dependency-satisfied nodes are in the ready-set
for i in ready:
    unmet = [d for d in by_id[i]["depends_on"] if d not in done]
    if unmet: fail.append(f"A1 {i}: unmet depends_on {unmet}")
# A2: 0 blocked / draft / unconfirmed / eval!=pass / readiness!=complete
for i in ready:
    n = by_id[i]
    for label, got, want in (("status", n["status"], "active"),
                             ("confirmation_status", n["confirmation_status"], "confirmed"),
                             ("evaluation_status", n["evaluation_status"], "pass"),
                             ("readiness", n["implementation_readiness"]["status"], "complete")):
        if got != want: fail.append(f"A2 {i}: {label}={got} (want {want})")
# completeness: every eligible node must appear
eligible = sorted(i for i, n in by_id.items()
                  if n["status"] == "active" and n["confirmation_status"] == "confirmed"
                  and n["evaluation_status"] == "pass"
                  and n["implementation_readiness"]["status"] == "complete"
                  and all(d in done for d in n["depends_on"]))
if eligible != sorted(ready): fail.append(f"A2b ready-set {sorted(ready)} != eligible {eligible}")
# A3: 0 resource_scope overlaps inside any batch
for kind, batches in rec["batches"].items():
    for bi, batch in enumerate(batches):
        if len(batch) > MAX_PARALLEL: fail.append(f"A3 {kind} batch{bi}: size {len(batch)} > max_parallel {MAX_PARALLEL}")
        for a, b in itertools.combinations(batch, 2):
            ov = set(by_id[a]["resource_scope"]) & set(by_id[b]["resource_scope"])
            if ov: fail.append(f"A3 {kind} batch{bi}: {a} x {b} overlap {sorted(ov)}")
# A4: unique suggested_branch and claim command
hints = rec["assignment_hints"]
br = [h["suggested_branch"] for h in hints]; cc = [h["claim_command"] for h in hints]
if len(set(br)) != len(br): fail.append("A4: duplicate suggested_branch")
if len(set(cc)) != len(cc): fail.append("A4: duplicate claim_command")
if sorted(h["graph_node_id"] for h in hints) != sorted(ready): fail.append("A4: hints != ready tasks")
for h in hints:
    i = h["graph_node_id"]
    if h["suggested_branch"] != f"devgraph/{i}": fail.append(f"A4 {i}: branch shape {h['suggested_branch']}")
    if not h["claim_command"].startswith(f"/dev-graph worktree claim {i} "): fail.append(f"A4 {i}: claim shape")
# separation + batch coverage
if feat: fail.append(f"A5: unexpected feature ready {feat}")
if sorted(x for b in rec["batches"]["tasks"] for x in b) != sorted(ready): fail.append("A5: batches != ready tasks")
if set(x for b in rec["batches"]["tasks"] for x in b) & set(x for b in rec["batches"]["features"] for x in b):
    fail.append("A5: feature/task batches mixed")

excluded = {i: n for i, n in by_id.items() if i not in ready}
print(json.dumps({
  "ready_tasks": ready, "ready_features": feat,
  "batches": rec["batches"], "conflicts": rec["conflicts"],
  "excluded": {i: f"status={n['status']}, confirm={n['confirmation_status']}, eval={n['evaluation_status']}, readiness={n['implementation_readiness']['status']}, unmet_deps={[d for d in n['depends_on'] if d not in done]}" for i, n in sorted(excluded.items())},
  "failures": fail, "acceptance": "PASS" if not fail else "FAIL"}, ensure_ascii=False, indent=1))
